import hashlib, hmac
target = "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"
t_cloze = "cbc9514f43d8f5d840b09d0b1332137335a0c647a14f1096b4e7b3ef49c7ada2"
algos = sorted(hashlib.algorithms_available)
print(algos)
s = b"ab"
def check(name, d):
    hx = d.hex() if isinstance(d, bytes) else d
    if hx.startswith(target[:10]): print("FOUND basic", name)
    if hx.startswith(t_cloze[:10]): print("FOUND cloze", name)
for alg in algos:
    try:
        h = hashlib.new(alg, s)
        d = h.hexdigest() if 'shake' not in alg else h.hexdigest(32)
        check(alg, d)
        # double
        h2 = hashlib.new(alg, bytes.fromhex(d)); d2 = h2.hexdigest() if 'shake' not in alg else h2.hexdigest(32)
        check(alg+"-double", d2)
        h3 = hashlib.new(alg, d.encode()); d3 = h3.hexdigest() if 'shake' not in alg else h3.hexdigest(32)
        check(alg+"-doublehex", d3)
    except Exception as e:
        pass
# utf16
for enc in ['utf-16-le','utf-16-be','utf-32-le']:
    check("sha256 "+enc, hashlib.sha256("ab".encode(enc)).digest())
# prefixes
for p in ["basic","Basic","BASIC","b","B","0","1","\x00","\x01","basic:","basic\n","Basic:","Basic\n","Q","question","front","card","Card","hashcards","hashcards:", "sha256:", "v1", "card:"]:
    for suf in ["", "\n", "\x00"]:
        for mid in ["", ":", "\n", " ", "\x00"]:
            v = (p+mid+"ab"+suf).encode()
            check(f"sha256 {p!r}{mid!r}{suf!r}", hashlib.sha256(v).digest())
            check(f"sha3 {p!r}{mid!r}{suf!r}", hashlib.sha3_256(v).digest())
            check(f"blake2s {p!r}{mid!r}{suf!r}", hashlib.blake2s(v).digest())
            check(f"blake2b256 {p!r}{mid!r}{suf!r}", hashlib.blake2b(v, digest_size=32).digest())
# hmac
for key in [b"", b"hashcards", b"basic"]:
    check(f"hmac {key}", hmac.new(key, s, 'sha256').digest())
print("done")
EOF"}

