        check(f"{name} pre {i}", fn(bytes([i]) + s))
        check(f"{name} suf {i}", fn(s + bytes([i])))
        check(f"{name} pre+suf {i}", fn(bytes([i]) + s + bytes([i])))
    for n in range(0, 16):
        for fmt in ['<I','<Q','>I','>Q','<H','>H','<B']:
            check(f"{name} int pre {fmt} {n}", fn(struct.pack(fmt, n) + s))
            check(f"{name} int suf {fmt} {n}", fn(s + struct.pack(fmt, n)))
