impl Connection {
    fn error(db: *mut sqlite3, code: c_int) -> SqliteError {
        let (message, extended) = if db.is_null() {
            (None, code)
        } else {
            let msg = unsafe { CStr::from_ptr(sqlite3_errmsg(db)) }
                .to_string_lossy()
                .into_owned();
            let ext = unsafe { sqlite3_extended_errcode(db) };
            (Some(msg), ext)
        };
        SqliteError {
            code: ErrorCode::from_primary(code),
            extended_code: extended,
            message,
        }
    }

    pub fn open(path: &std::path::Path) -> Result<Connection, SqliteError> {
        let path_str = path.to_string_lossy().into_owned();
        let c_path = CString::new(path_str.clone()).map_err(|_| SqliteError {
            code: ErrorCode::Unknown,
            extended_code: 1,
            message: Some("invalid path".into()),
        })?;
        let mut db: *mut sqlite3 = ptr::null_mut();
        let flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_NOMUTEX | SQLITE_OPEN_URI;
        let rc = unsafe { sqlite3_open_v2(c_path.as_ptr(), &mut db, flags, ptr::null()) };
        if rc != SQLITE_OK {
            let mut e = if db.is_null() {
                SqliteError {
                    code: ErrorCode::from_primary(rc),
                    extended_code: rc,
                    message: Some(path_str.clone()),
                }
            } else {
                Self::error(db, rc)
            };
            if e.code == ErrorCode::CannotOpen {
                if let Some(msg) = e.message.take() {
                    e.message = Some(format!("{}: {}", msg, path_str));
                }
                e.extended_code = rc;
            }
            if !db.is_null() {
                unsafe {
                    sqlite3_close(db);
                }
            }
            return Err(e);
        }
        Ok(Connection { db })
    }

    pub fn execute_batch(&self, sql: &str) -> Result<(), SqliteError> {
        let mut rest = sql.trim();
        while !rest.is_empty() {
            let c_sql = CString::new(rest).unwrap();
            let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
            let mut tail: *const c_char = ptr::null();
            let rc = unsafe {
                sqlite3_prepare_v2(self.db, c_sql.as_ptr(), -1, &mut stmt, &mut tail)
            };
            if rc != SQLITE_OK {
                return Err(Self::error(self.db, rc));
            }
            let consumed = unsafe { tail.offset_from(c_sql.as_ptr()) } as usize;
            if !stmt.is_null() {
                let rc = unsafe { sqlite3_step(stmt) };
                unsafe {
                    sqlite3_finalize(stmt);
                }
                if rc != SQLITE_DONE && rc != SQLITE_ROW {
                    return Err(Self::error(self.db, rc));
                }
            }
            rest = rest[consumed..].trim();
        }
        Ok(())
    }

    fn prepare(&self, sql: &str, params: &[Value]) -> Result<*mut sqlite3_stmt, SqliteError> {
        let c_sql = CString::new(sql).unwrap();
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let rc = unsafe {
            sqlite3_prepare_v2(self.db, c_sql.as_ptr(), -1, &mut stmt, ptr::null_mut())
        };
        if rc != SQLITE_OK {
            return Err(Self::error(self.db, rc));
        }
        for (i, p) in params.iter().enumerate() {
            let idx = (i + 1) as c_int;
            let rc = unsafe {
                match p {
                    Value::Null => sqlite3_bind_null(stmt, idx),
                    Value::Integer(n) => sqlite3_bind_int64(stmt, idx, *n),
                    Value::Real(x) => sqlite3_bind_double(stmt, idx, *x),
                    Value::Text(s) => sqlite3_bind_text(
                        stmt,
                        idx,
                        s.as_ptr() as *const c_char,
                        s.len() as c_int,
                        SQLITE_TRANSIENT,
                    ),
                }
            };
            if rc != SQLITE_OK {
                let e = Self::error(self.db, rc);
                unsafe {
                    sqlite3_finalize(stmt);
                }
                return Err(e);
            }
        }
        Ok(stmt)
    }

    /// Execute a statement that returns no rows.
    pub fn execute(&self, sql: &str, params: &[Value]) -> Result<(), SqliteError> {
        let stmt = self.prepare(sql, params)?;
        let rc = unsafe { sqlite3_step(stmt) };
        let result = if rc == SQLITE_DONE || rc == SQLITE_ROW {
            Ok(())
        } else {
            Err(Self::error(self.db, rc))
        };
        unsafe {
            sqlite3_reset(stmt);
            sqlite3_finalize(stmt);
        }
        result
    }

    /// Execute a query and collect all rows.
    pub fn query(&self, sql: &str, params: &[Value]) -> Result<Vec<Row>, SqliteError> {
        let stmt = self.prepare(sql, params)?;
        let ncols = unsafe { sqlite3_column_count(stmt) };
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                let mut cols = Vec::with_capacity(ncols as usize);
                for i in 0..ncols {
                    let ty = unsafe { sqlite3_column_type(stmt, i) };
                    let v = match ty {
                        SQLITE_INTEGER => Value::Integer(unsafe { sqlite3_column_int64(stmt, i) }),
                        SQLITE_FLOAT => Value::Real(unsafe { sqlite3_column_double(stmt, i) }),
                        SQLITE_TEXT => {
                            let p = unsafe { sqlite3_column_text(stmt, i) };
                            let n = unsafe { sqlite3_column_bytes(stmt, i) } as usize;
                            let bytes = if p.is_null() {
                                &[][..]
                            } else {
                                unsafe { std::slice::from_raw_parts(p, n) }
                            };
                            Value::Text(String::from_utf8_lossy(bytes).into_owned())
                        }
                        SQLITE_NULL => Value::Null,
                        _ => {
                            // BLOB: treat as text.
                            let p = unsafe { sqlite3_column_text(stmt, i) };
                            let n = unsafe { sqlite3_column_bytes(stmt, i) } as usize;
                            let bytes = if p.is_null() {
                                &[][..]
                            } else {
                                unsafe { std::slice::from_raw_parts(p, n) }
                            };
                            Value::Text(String::from_utf8_lossy(bytes).into_owned())
                        }
                    };
                    cols.push(v);
                }
                rows.push(Row { cols });
            } else if rc == SQLITE_DONE {
                break;
            } else {
                let e = Self::error(self.db, rc);
                unsafe {
                    sqlite3_finalize(stmt);
                }
                return Err(e);
            }
        }
        unsafe {
            sqlite3_finalize(stmt);
        }
        Ok(rows)
    }

    pub fn query_one(&self, sql: &str, params: &[Value]) -> Result<Option<Row>, SqliteError> {
        let mut rows = self.query(sql, params)?;
        if rows.is_empty() {
            Ok(None)
        } else {
            Ok(Some(rows.remove(0)))
        }
    }

    pub fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }
}

impl Drop for Connection {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe {
                sqlite3_close(self.db);
            }
            self.db = ptr::null_mut();
        }
    }
}
