//! Parsing of Markdown deck files into cards.

use crate::blake3;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
pub enum CardContent {
    Basic { question: String, answer: String },
    Cloze { text: String, start: u64, end: u64 },
}

#[derive(Debug, Clone)]
pub struct Card {
    pub hash: String,
    pub family_hash: Option<String>,
    pub deck_name: String,
    pub file_path: PathBuf,
    pub line_start: usize,
    pub line_end: usize,
    pub content: CardContent,
}

impl Card {
    pub fn is_cloze(&self) -> bool {
        matches!(self.content, CardContent::Cloze { .. })
    }
}

#[derive(Debug)]
pub enum ParseError {
    /// A structural parse error with a location (file and 1-based line).
    Syntax { message: String, file: PathBuf, line: usize },
    /// Frontmatter was opened but never closed.
    UnclosedFrontmatter,
    /// The frontmatter was not valid TOML.
    Toml(String),
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::Syntax { message, file, line } => {
                write!(f, "Parse error: {} Location: {}:{}", message, file.display(), line)
            }
            ParseError::UnclosedFrontmatter => {
                write!(f, "Frontmatter opening '---' found but no closing '---'")
            }
            ParseError::Toml(e) => write!(f, "Failed to parse TOML frontmatter: {}", e),
        }
    }
}

#[derive(serde::Deserialize, Default)]
struct Frontmatter {
    name: Option<String>,
}

pub fn hash_content(content: &CardContent) -> String {
    let mut h = blake3::Hasher::new();
    match content {
        CardContent::Basic { question, answer } => {
            h.update(b"Basic");
            h.update(question.as_bytes());
            h.update(answer.as_bytes());
        }
        CardContent::Cloze { text, start, end } => {
            h.update(b"Cloze");
            h.update(text.as_bytes());
            h.update(&start.to_le_bytes());
            h.update(&end.to_le_bytes());
        }
    }
    blake3::to_hex(&h.finalize())
}

pub fn family_hash(text: &str) -> String {
    let mut h = blake3::Hasher::new();
    h.update(b"Cloze");
    h.update(text.as_bytes());
    blake3::to_hex(&h.finalize())
}

enum State {
    Idle,
    Question { start: usize, lines: Vec<String> },
    Answer { start: usize, question: String, lines: Vec<String> },
    Cloze { start: usize, lines: Vec<String> },
}

fn join_trim(lines: &[String]) -> String {
    lines.join("\n").trim().to_string()
}

/// Parse a cloze card's text: brackets are stripped, and each `[...]` pair
/// becomes a cloze deletion with inclusive byte offsets.
fn parse_cloze_text(raw: &str) -> (String, Vec<(u64, u64)>) {
    let mut text = String::with_capacity(raw.len());
    let mut clozes = Vec::new();
    let mut start: Option<usize> = None;
    for c in raw.chars() {
        match c {
            '[' => {
                start = Some(text.len());
            }
            ']' => {
                if let Some(s) = start.take() {
                    let end = (text.len() as u64).wrapping_sub(1);
                    clozes.push((s as u64, end));
                }
            }
            _ => text.push(c),
        }
    }
    (text, clozes)
}

/// Parse a deck file's contents into cards.
pub fn parse_deck(
    path: &Path,
    default_deck_name: &str,
    contents: &str,
) -> Result<Vec<Card>, ParseError> {
    let all_lines: Vec<&str> = contents.lines().collect();
    let mut deck_name = default_deck_name.to_string();
    let mut content_lines: &[&str] = &all_lines;

    // Frontmatter.
    if let Some(first) = all_lines.first() {
        if first.trim() == "---" {
            let mut close = None;
            for (i, l) in all_lines.iter().enumerate().skip(1) {
                if l.trim() == "---" {
                    close = Some(i);
                    break;
                }
            }
            let close = match close {
                Some(c) => c,
                None => return Err(ParseError::UnclosedFrontmatter),
            };
            let toml_text = all_lines[1..close].join("\n");
            let fm: Frontmatter = match toml::from_str(&toml_text) {
                Ok(fm) => fm,
                Err(e) => return Err(ParseError::Toml(e.to_string())),
            };
            if let Some(name) = fm.name {
                deck_name = name;
            }
            content_lines = &all_lines[close + 1..];
        }
    }

    let mut cards: Vec<Card> = Vec::new();
    let mut state = State::Idle;
    let nlines = content_lines.len();

    let err = |message: &str, line: usize| ParseError::Syntax {
        message: message.to_string(),
        file: path.to_path_buf(),
        line,
    };

    let mut finish_basic = |cards: &mut Vec<Card>, start: usize, end: usize, question: String, lines: &[String]| {
        let answer = join_trim(lines);
        let content = CardContent::Basic { question, answer };
        let hash = hash_content(&content);
        cards.push(Card {
            hash,
            family_hash: None,
            deck_name: deck_name.clone(),
            file_path: path.to_path_buf(),
            line_start: start,
            line_end: end,
            content,
        });
    };

    let finish_cloze = |cards: &mut Vec<Card>, deck_name: &str, start: usize, end: usize, lines: &[String]| -> Result<(), ParseError> {
        let raw = join_trim(lines);
        let (text, clozes) = parse_cloze_text(&raw);
        if clozes.is_empty() {
            return Err(ParseError::Syntax {
                message: "Cloze card must contain at least one cloze deletion.".to_string(),
                file: path.to_path_buf(),
                line: start + 1,
            });
        }
        let family = family_hash(&text);
        for (s, e) in clozes {
            let content = CardContent::Cloze {
                text: text.clone(),
                start: s,
                end: e,
            };
            let hash = hash_content(&content);
            cards.push(Card {
                hash,
                family_hash: Some(family.clone()),
                deck_name: deck_name.to_string(),
                file_path: path.to_path_buf(),
                line_start: start,
                line_end: end,
                content,
            });
        }
        Ok(())
    };

    for (i, line) in content_lines.iter().enumerate() {
        let is_q = line.starts_with("Q:");
        let is_a = line.starts_with("A:");
        let is_c = line.starts_with("C:");
        let is_sep = line.trim() == "---";
        let tag_rest = |l: &str| l[2..].trim().to_string();

        state = match state {
            State::Idle => {
                if is_q {
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag without a question.", i + 1));
                } else if is_c {
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else {
                    State::Idle
                }
            }
            State::Question { start, mut lines } => {
                if is_q {
                    return Err(err("New question without answer.", i + 1));
                } else if is_a {
                    let question = join_trim(&lines);
                    State::Answer { start, question, lines: vec![tag_rest(line)] }
                } else if is_c {
                    return Err(err("Found cloze tag while reading a question.", i + 1));
                } else if is_sep {
                    return Err(err("Found flashcard separator while reading a question.", i + 1));
                } else {
                    lines.push(line.to_string());
                    State::Question { start, lines }
                }
            }
            State::Answer { start, question, mut lines } => {
                if is_q {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag while reading an answer.", i + 1));
                } else if is_c {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else if is_sep {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Idle
                } else {
                    lines.push(line.to_string());
                    State::Answer { start, question, lines }
                }
            }
            State::Cloze { start, mut lines } => {
                if is_q {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag while reading a cloze card.", i + 1));
                } else if is_c {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else if is_sep {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Idle
                } else {
                    lines.push(line.to_string());
                    State::Cloze { start, lines }
                }
            }
        };
    }

    let last = nlines.saturating_sub(1);
    match state {
        State::Idle => {}
        State::Question { .. } => {
            return Err(err(
                "File ended while reading a question without an answer.",
                nlines,
            ));
        }
        State::Answer { start, question, lines } => {
            finish_basic(&mut cards, start, last, question, &lines);
        }
        State::Cloze { start, lines } => {
            finish_cloze(&mut cards, &deck_name, start, last, &lines)?;
        }
    }

    Ok(cards)
}
