        file: path.to_path_buf(),
        line,
    };

    let mut finish_basic = |cards: &mut Vec<Card>, start: usize, end: usize, question: String, lines: &[String]| {
        let answer = join_trim(lines);
        let content = CardContent::Basic { question, answer };
        let hash = hash_content(&content);
        cards.push(Card {
            hash,
            family_hash: None,
            deck_name: deck_name.clone(),
            file_path: path.to_path_buf(),
            line_start: start,
            line_end: end,
            content,
        });
    };

    let finish_cloze = |cards: &mut Vec<Card>, deck_name: &str, start: usize, end: usize, lines: &[String]| -> Result<(), ParseError> {
        let raw = join_trim(lines);
        let (text, clozes) = parse_cloze_text(&raw);
        if clozes.is_empty() {
            return Err(ParseError::Syntax {
                message: "Cloze card must contain at least one cloze deletion.".to_string(),
                file: path.to_path_buf(),
                line: start + 1,
            });
        }
        let family = family_hash(&text);
        for (s, e) in clozes {
            let content = CardContent::Cloze {
                text: text.clone(),
                start: s,
                end: e,
            };
            let hash = hash_content(&content);
            cards.push(Card {
                hash,
                family_hash: Some(family.clone()),
                deck_name: deck_name.to_string(),
                file_path: path.to_path_buf(),
                line_start: start,
                line_end: end,
                content,
            });
        }
        Ok(())
    };

    for (i, line) in content_lines.iter().enumerate() {
        let is_q = line.starts_with("Q:");
        let is_a = line.starts_with("A:");
        let is_c = line.starts_with("C:");
        let is_sep = line.trim() == "---";
        let tag_rest = |l: &str| l[2..].trim().to_string();

        state = match state {
            State::Idle => {
                if is_q {
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag without a question.", i + 1));
                } else if is_c {
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else {
                    State::Idle
                }
            }
            State::Question { start, mut lines } => {
                if is_q {
                    return Err(err("New question without answer.", i + 1));
                } else if is_a {
                    let question = join_trim(&lines);
                    State::Answer { start, question, lines: vec![tag_rest(line)] }
                } else if is_c {
                    return Err(err("Found cloze tag while reading a question.", i + 1));
                } else if is_sep {
                    return Err(err("Found flashcard separator while reading a question.", i + 1));
                } else {
                    lines.push(line.to_string());
                    State::Question { start, lines }
                }
            }
            State::Answer { start, question, mut lines } => {
                if is_q {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag while reading an answer.", i + 1));
                } else if is_c {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else if is_sep {
                    finish_basic(&mut cards, start, i, question, &lines);
                    State::Idle
                } else {
                    lines.push(line.to_string());
                    State::Answer { start, question, lines }
                }
            }
            State::Cloze { start, mut lines } => {
                if is_q {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Question { start: i, lines: vec![tag_rest(line)] }
                } else if is_a {
                    return Err(err("Found answer tag while reading a cloze card.", i + 1));
                } else if is_c {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Cloze { start: i, lines: vec![tag_rest(line)] }
                } else if is_sep {
                    finish_cloze(&mut cards, &deck_name, start, i, &lines)?;
                    State::Idle
                } else {
                    lines.push(line.to_string());
                    State::Cloze { start, lines }
                }
            }
        };
    }

    let last = nlines.saturating_sub(1);
    match state {
        State::Idle => {}
        State::Question { .. } => {
            return Err(err(
                "File ended while reading a question without an answer.",
                nlines,
            ));
        }
        State::Answer { start, question, lines } => {
            finish_basic(&mut cards, start, last, question, &lines);
        }
        State::Cloze { start, lines } => {
            finish_cloze(&mut cards, &deck_name, start, last, &lines)?;
        }
    }

    Ok(cards)
}
