//! Loading a collection of decks from a directory.

use crate::error::Error;
use crate::parser::{parse_deck, Card, CardContent};
use std::collections::HashSet;
use std::path::{Path, PathBuf};

pub struct Collection {
    pub root: PathBuf,
    pub cards: Vec<Card>,
    pub macros: Vec<(String, String)>,
}

/// Recursively walk a directory in directory-entry order (depth first),
/// collecting regular files.
fn walk(dir: &Path, depth: usize, out: &mut Vec<PathBuf>) -> Result<(), Error> {
    let rd = match std::fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(e) => {
            return Err(Error::Walk {
                depth,
                path: dir.to_path_buf(),
                err: e,
            })
        }
    };
    for entry in rd {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => {
                return Err(Error::Walk {
                    depth,
                    path: dir.to_path_buf(),
                    err: e,
                })
            }
        };
        let path = entry.path();
        let ft = match entry.file_type() {
            Ok(ft) => ft,
            Err(e) => {
                return Err(Error::Walk {
                    depth: depth + 1,
                    path: path.clone(),
                    err: e,
                })
            }
        };
        if ft.is_dir() {
            walk(&path, depth + 1, out)?;
        } else {
            out.push(path);
        }
    }
    Ok(())
}

pub fn parse_macros(contents: &str) -> Vec<(String, String)> {
    let mut macros = Vec::new();
    for line in contents.lines() {
        if line.trim().starts_with('%') {
            continue;
        }
        if let Some((name, def)) = line.split_once(' ') {
            macros.push((name.to_string(), def.to_string()));
        }
    }
    macros
}

/// Percent-decode a string (invalid sequences are kept as-is).
pub fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 && i + 2 <= bytes.len() - 1 {
            let h = (bytes[i + 1] as char).to_digit(16);
            let l = (bytes[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// Resolve a media reference to an on-disk path, if it exists.
/// Returns the existing path (decoded form preferred) or None.
pub fn resolve_media(root: &Path, deck_dir: &Path, url: &str) -> Option<PathBuf> {
    let (base, rel) = if let Some(rest) = url.strip_prefix("@/") {
        (root, rest)
    } else {
        (deck_dir, url)
    };
    let decoded = percent_decode(rel);
    let p = base.join(&decoded);
    if p.exists() {
        return Some(p);
    }
    let p2 = base.join(rel);
    if p2.exists() {
        return Some(p2);
    }
    None
}

pub fn media_display_name(url: &str) -> String {
    if let Some(rest) = url.strip_prefix("@/") {
        format!("@/{}", percent_decode(rest))
    } else {
        percent_decode(url)
    }
}

fn card_texts(card: &Card) -> Vec<&str> {
    match &card.content {
        CardContent::Basic { question, answer } => vec![question.as_str(), answer.as_str()],
        CardContent::Cloze { text, .. } => vec![text.as_str()],
    }
}

/// Load the collection at `root` (which must already be canonical).
pub fn load(root: &Path) -> Result<Collection, Error> {
    // TeX macros.
    let macros_path = root.join("macros.tex");
    let macros = if macros_path.is_file() {
        let contents = std::fs::read_to_string(&macros_path).map_err(Error::Io)?;
        parse_macros(&contents)
    } else {
        Vec::new()
    };

    // Decks.
    let mut files = Vec::new();
    walk(root, 0, &mut files)?;
    let mut cards: Vec<Card> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    for file in files {
        if file.extension().and_then(|e| e.to_str()) != Some("md") {
            continue;
        }
        let canonical = std::fs::canonicalize(&file).map_err(Error::Io)?;
        if canonical.strip_prefix(root).is_err() {
            return Err(Error::StripPrefix);
        }
        let contents = std::fs::read_to_string(&canonical).map_err(Error::Io)?;
        let stem = canonical
            .file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_default();
        let deck_cards = parse_deck(&canonical, &stem, &contents).map_err(Error::Parse)?;
        for card in deck_cards {
            if seen.insert(card.hash.clone()) {
                cards.push(card);
            }
        }
    }

    // Media check.
    let mut missing: Vec<(String, PathBuf, usize)> = Vec::new();
    for card in &cards {
        let deck_dir = card.file_path.parent().unwrap_or(root).to_path_buf();
        for text in card_texts(card) {
            for url in crate::markdown::image_urls(text) {
                if resolve_media(root, &deck_dir, &url).is_none() {
                    missing.push((media_display_name(&url), card.file_path.clone(), card.line_start));
                }
            }
        }
    }
    if !missing.is_empty() {
        missing.sort();
        missing.dedup();
        return Err(Error::MissingMedia(missing));
    }

    Ok(Collection {
        root: root.to_path_buf(),
        cards,
        macros,
    })
}
