cat > src/main.rs <<'EOF'
mod blake3;
mod collection;
mod db;
mod error;
mod export;
mod fsrs;
mod html;
mod markdown;
mod parser;
mod server;
mod sqlite;
mod stats;

use clap::builder::PossibleValue;
use clap::{value_parser, Arg, ArgAction, Command};
use error::Error;
use std::path::{Path, PathBuf};

fn directory_arg() -> Arg {
    Arg::new("directory")
        .value_name("DIRECTORY")
        .help("Path to the collection directory. By default, the current working directory is used")
        .value_parser(value_parser!(PathBuf))
}

fn build_cli() -> Command {
    Command::new("hashcards")
        .version("0.3.0")
        .about("A plain text-based spaced repetition system.")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("drill")
                .about("Drill cards through a web interface")
                .arg(directory_arg())
                .arg(
                    Arg::new("card-limit")
                        .long("card-limit")
                        .value_name("CARD_LIMIT")
                        .help("Maximum number of cards to drill in a session. By default, all cards due today are drilled")
                        .value_parser(value_parser!(usize)),
                )
                .arg(
                    Arg::new("new-card-limit")
                        .long("new-card-limit")
                        .value_name("NEW_CARD_LIMIT")
                        .help("Maximum number of new cards to drill in a session")
                        .value_parser(value_parser!(usize)),
                )
                .arg(
                    Arg::new("host")
                        .long("host")
                        .value_name("HOST")
                        .help("The host address to bind to. Default is 127.0.0.1")
                        .default_value("127.0.0.1"),
                )
                .arg(
                    Arg::new("port")
                        .long("port")
                        .value_name("PORT")
                        .help("The port to use for the web server. Default is 8000")
                        .default_value("8000")
                        .value_parser(value_parser!(u16)),
                )
                .arg(
                    Arg::new("from-deck")
                        .long("from-deck")
                        .value_name("FROM_DECK")
                        .help("Only drill cards from this deck"),
                )
                .arg(
                    Arg::new("open-browser")
                        .long("open-browser")
                        .value_name("OPEN_BROWSER")
                        .help("Whether to open the browser automatically. Default is true")
                        .value_parser(value_parser!(bool)),
                )
                .arg(
                    Arg::new("answer-controls")
                        .long("answer-controls")
                        .value_name("ANSWER_CONTROLS")
                        .help("Which answer controls to show:")
                        .default_value("full")
                        .value_parser([
                            PossibleValue::new("full")
                                .help("Show all four rating buttons (Forgot/Hard/Good/Easy)"),
                            PossibleValue::new("binary")
                                .help("Show only two rating buttons (Forgot/Good)"),
                        ]),
                )
                .arg(
                    Arg::new("bury-siblings")
                        .long("bury-siblings")
                        .value_name("BURY_SIBLINGS")
                        .help("Whether or not to bury siblings. Default is true")
                        .value_parser(value_parser!(bool)),
                ),
        )
        .subcommand(
            Command::new("check")
                .about("Check the integrity of a collection")
                .arg(directory_arg()),
        )
        .subcommand(
            Command::new("stats")
                .about("Print collection statistics")
                .arg(directory_arg())
                .arg(
                    Arg::new("format")
                        .long("format")
                        .value_name("FORMAT")
                        .help("Which output format to use")
                        .default_value("html")
                        .value_parser([
                            PossibleValue::new("html").help("HTML output"),
                            PossibleValue::new("json").help("JSON output"),
                        ]),
                ),
        )
        .subcommand(
            Command::new("orphans")
                .about("Commands relating to orphan cards")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .subcommand(
                    Command::new("list")
                        .about("List the hashes of all orphan cards in the collection")
                        .arg(directory_arg()),
                )
                .subcommand(
                    Command::new("delete")
                        .about("Remove all orphan cards from the database")
                        .arg(directory_arg()),
                ),
        )
        .subcommand(
            Command::new("export")
                .about("Export a collection")
                .arg(directory_arg())
                .arg(
                    Arg::new("output")
                        .long("output")
                        .value_name("OUTPUT")
                        .help("Optional path to the output file. By default, the output is printed to stdout")
                        .value_parser(value_parser!(PathBuf))
                        .action(ArgAction::Set),
                ),
        )
}

/// Resolve and validate the collection directory, open the database.
fn open_collection_dir(dir: Option<&PathBuf>) -> Result<(PathBuf, db::Database), Error> {
    let dir: PathBuf = match dir {
        Some(d) => d.clone(),
        None => std::env::current_dir().map_err(Error::Io)?,
    };
    if !dir.exists() {
        return Err(Error::DirectoryDoesNotExist);
    }
    let dir = std::fs::canonicalize(&dir).map_err(Error::Io)?;
    let database = db::Database::open(&dir.join("hashcards.db"))?;
    Ok((dir, database))
}

fn run() -> Result<(), Error> {
    let matches = build_cli().get_matches();
    match matches.subcommand() {
        Some(("drill", sub)) => {
            let dir = sub.get_one::<PathBuf>("directory");
