//! Error type for the application.

use crate::parser::ParseError;
use crate::sqlite::SqliteError;
use std::path::PathBuf;

#[derive(Debug)]
pub enum Error {
    DirectoryDoesNotExist,
    Sqlite(SqliteError),
    Io(std::io::Error),
    Parse(ParseError),
    MissingMedia(Vec<(String, PathBuf, usize)>),
    Walk {
        depth: usize,
        path: PathBuf,
        err: std::io::Error,
    },
    StripPrefix,
    Other(String),
}

impl From<SqliteError> for Error {
    fn from(e: SqliteError) -> Error {
        Error::Sqlite(e)
    }
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Error {
        Error::Io(e)
    }
}

/// Indent every line of a `{:#?}`-style rendering by `n` spaces (except the first).
fn indent_debug(s: &str, n: usize) -> String {
    let pad = " ".repeat(n);
    let mut out = String::new();
    for (i, line) in s.lines().enumerate() {
        if i > 0 {
            out.push('\n');
            out.push_str(&pad);
        }
        out.push_str(line);
    }
    out
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::DirectoryDoesNotExist => write!(f, "directory does not exist."),
            Error::Sqlite(e) => write!(f, "rusqlite: {}", e),
            Error::Io(e) => write!(f, "I/O error: {:#?}", e),
            Error::Parse(e) => write!(f, "{}", e),
            Error::MissingMedia(items) => {
                writeln!(f, "Missing media files referenced in cards:")?;
                for (name, path, line) in items {
                    writeln!(f, "  - {} (referenced in {}:{})", name, path.display(), line)?;
                }
                Ok(())
            }
            Error::Walk { depth, path, err } => {
                let err_dbg = indent_debug(&format!("{:#?}", err), 8);
                write!(
                    f,
                    "directory traversal error: Error {{\n    depth: {},\n    inner: Io {{\n        path: Some(\n            {:?},\n        ),\n        err: {},\n    }},\n}}",
                    depth,
                    path.to_string_lossy(),
                    err_dbg
                )
            }
            Error::StripPrefix => write!(f, "Strip prefix error: StripPrefixError(\n    (),\n)"),
            Error::Other(s) => write!(f, "{}", s),
        }
    }
}
