//! The collection database.

use crate::collection::Collection;
use crate::error::Error;
use crate::sqlite::{Connection, Value};
use chrono::{DateTime, NaiveDate, Utc};
use std::collections::HashSet;
use std::path::Path;

pub const TIMESTAMP_FORMAT: &str = "%Y-%m-%dT%H:%M:%S%.3f";
pub const DATE_FORMAT: &str = "%Y-%m-%d";

pub fn format_timestamp(t: &DateTime<Utc>) -> String {
    t.format(TIMESTAMP_FORMAT).to_string()
}

pub fn format_date(d: &NaiveDate) -> String {
    d.format(DATE_FORMAT).to_string()
}

#[derive(Debug, Clone)]
pub struct Performance {
    pub last_reviewed_at: String,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: String,
    pub review_count: i64,
}

impl Performance {
    pub fn last_reviewed_date(&self) -> Option<NaiveDate> {
        chrono::NaiveDateTime::parse_from_str(&self.last_reviewed_at, TIMESTAMP_FORMAT)
            .map(|dt| dt.date())
            .ok()
            .or_else(|| NaiveDate::parse_from_str(&self.last_reviewed_at[..self.last_reviewed_at.len().min(10)], DATE_FORMAT).ok())
    }
    pub fn due_date(&self) -> Option<NaiveDate> {
        NaiveDate::parse_from_str(&self.due_date, DATE_FORMAT).ok()
    }
}

#[derive(Debug, Clone)]
pub struct ReviewRow {
    pub review_id: i64,
    pub card_hash: String,
    pub reviewed_at: String,
    pub grade: String,
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
    pub due_date: String,
}

#[derive(Debug, Clone)]
pub struct SessionRow {
    pub session_id: i64,
    pub started_at: String,
    pub ended_at: String,
    pub reviews: Vec<ReviewRow>,
}

pub struct Database {
    conn: Connection,
}

const SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS cards (
    card_hash text primary key,
    added_at text not null,
    last_reviewed_at text,
    stability real,
    difficulty real,
    interval_raw real,
    interval_days integer,
    due_date text,
    review_count integer not null
) strict;

CREATE TABLE IF NOT EXISTS sessions (
    session_id integer primary key,
    started_at text not null,
    ended_at text not null
) strict;

CREATE TABLE IF NOT EXISTS reviews (
    review_id integer primary key,
    session_id integer not null
        references sessions (session_id)
        on update cascade
        on delete cascade,
    card_hash text not null
        references cards (card_hash)
        on update cascade
        on delete cascade,
    reviewed_at text not null,
    grade text not null,
    stability real not null,
    difficulty real not null,
    interval_raw real not null,
    interval_days integer not null,
    due_date text not null
) strict;
";

impl Database {
    pub fn open(path: &Path) -> Result<Database, Error> {
        let conn = Connection::open(path)?;
        conn.execute_batch("PRAGMA foreign_keys = ON;")?;
        conn.execute_batch(SCHEMA)?;
        Ok(Database { conn })
    }

    pub fn begin(&self) -> Result<(), Error> {
        self.conn.execute_batch("BEGIN;")?;
        Ok(())
    }

    pub fn commit(&self) -> Result<(), Error> {
        self.conn.execute_batch("COMMIT;")?;
        Ok(())
    }

    pub fn card_count(&self) -> Result<i64, Error> {
        let row = self.conn.query_one("SELECT COUNT(*) FROM cards", &[])?;
        Ok(row.map(|r| r.int(0)).unwrap_or(0))
    }

    pub fn reviews_today_count(&self, today: &NaiveDate) -> Result<i64, Error> {
        let start = format_date(today);
        let end = format_date(&(*today + chrono::Duration::days(1)));
        let row = self.conn.query_one(
            "SELECT COUNT(*) FROM reviews WHERE reviewed_at >= ? AND reviewed_at < ?",
            &[Value::from(start), Value::from(end)],
        )?;
        Ok(row.map(|r| r.int(0)).unwrap_or(0))
    }

    pub fn all_card_hashes(&self) -> Result<Vec<String>, Error> {
        let rows = self.conn.query("SELECT card_hash FROM cards ORDER BY card_hash", &[])?;
        Ok(rows.iter().map(|r| r.text(0)).collect())
    }

    /// Hashes of cards in the database that are not in the collection.
    pub fn orphans(&self, coll: &Collection) -> Result<Vec<String>, Error> {
        let present: HashSet<&str> = coll.cards.iter().map(|c| c.hash.as_str()).collect();
        let mut result: Vec<String> = self
            .all_card_hashes()?
            .into_iter()
            .filter(|h| !present.contains(h.as_str()))
            .collect();
        result.sort();
        Ok(result)
    }

    pub fn delete_card(&self, hash: &str) -> Result<(), Error> {
        self.conn
            .execute("DELETE FROM cards WHERE card_hash = ?", &[Value::from(hash)])?;
        Ok(())
    }

    pub fn insert_card_if_missing(&self, hash: &str, now: &str) -> Result<(), Error> {
        self.conn.execute(
            "INSERT OR IGNORE INTO cards (card_hash, added_at, review_count) VALUES (?, ?, 0)",
            &[Value::from(hash), Value::from(now)],
        )?;
        Ok(())
    }

    pub fn performance(&self, hash: &str) -> Result<Option<Performance>, Error> {
        let row = self.conn.query_one(
            "SELECT last_reviewed_at, stability, difficulty, interval_raw, interval_days, due_date, review_count FROM cards WHERE card_hash = ?",
            &[Value::from(hash)],
        )?;
        Ok(row.and_then(|r| {
            let last = r.opt_text(0)?;
            Some(Performance {
                last_reviewed_at: last,
                stability: r.opt_real(1).unwrap_or(0.0),
                difficulty: r.opt_real(2).unwrap_or(0.0),
                interval_raw: r.opt_real(3).unwrap_or(0.0),
                interval_days: r.opt_int(4).unwrap_or(0),
                due_date: r.opt_text(5).unwrap_or_default(),
                review_count: r.int(6),
            })
        }))
    }

    pub fn update_card_performance(&self, hash: &str, p: &Performance) -> Result<(), Error> {
        self.conn.execute(
            "UPDATE cards SET last_reviewed_at = ?, stability = ?, difficulty = ?, interval_raw = ?, interval_days = ?, due_date = ?, review_count = ? WHERE card_hash = ?",
            &[
                Value::from(p.last_reviewed_at.as_str()),
                Value::from(p.stability),
                Value::from(p.difficulty),
                Value::from(p.interval_raw),
                Value::from(p.interval_days),
                Value::from(p.due_date.as_str()),
                Value::from(p.review_count),
                Value::from(hash),
            ],
        )?;
        Ok(())
    }

    pub fn insert_session(&self, started_at: &str, ended_at: &str) -> Result<i64, Error> {
        self.conn.execute(
            "INSERT INTO sessions (started_at, ended_at) VALUES (?, ?)",
            &[Value::from(started_at), Value::from(ended_at)],
        )?;
        Ok(self.conn.last_insert_rowid())
    }

    pub fn insert_review(&self, session_id: i64, r: &ReviewRow) -> Result<(), Error> {
        self.conn.execute(
            "INSERT INTO reviews (session_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            &[
                Value::from(session_id),
                Value::from(r.card_hash.as_str()),
                Value::from(r.reviewed_at.as_str()),
                Value::from(r.grade.as_str()),
                Value::from(r.stability),
                Value::from(r.difficulty),
                Value::from(r.interval_raw),
                Value::from(r.interval_days),
                Value::from(r.due_date.as_str()),
            ],
        )?;
        Ok(())
    }

    pub fn sessions(&self) -> Result<Vec<SessionRow>, Error> {
        let rows = self.conn.query(
            "SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id",
            &[],
        )?;
        let mut sessions = Vec::new();
        for r in rows {
            let session_id = r.int(0);
            let reviews = self.conn.query(
                "SELECT review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id = ? ORDER BY review_id",
                &[Value::from(session_id)],
            )?;
            sessions.push(SessionRow {
                session_id,
                started_at: r.text(1),
                ended_at: r.text(2),
                reviews: reviews
                    .iter()
                    .map(|rv| ReviewRow {
                        review_id: rv.int(0),
                        card_hash: rv.text(1),
                        reviewed_at: rv.text(2),
                        grade: rv.text(3),
                        stability: rv.real(4),
                        difficulty: rv.real(5),
                        interval_raw: rv.real(6),
                        interval_days: rv.int(7),
                        due_date: rv.text(8),
                    })
                    .collect(),
            });
        }
        Ok(sessions)
    }
}
