//! HTML escaping helpers (matching the conventions of common Markdown renderers).

/// Escape text for an HTML body (does not escape quotes).
pub fn escape_body(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
}

/// Escape text for an HTML attribute value (also escapes double quotes).
pub fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
}

pub fn escape_attr_string(s: &str) -> String {
    let mut out = String::new();
    escape_attr(s, &mut out);
    out
}

fn href_safe(b: u8) -> bool {
    if b < 0x20 || b >= 0x7f {
        return false;
    }
    !matches!(
        b,
        b' ' | b'"' | b'&' | b'\'' | b'<' | b'>' | b'[' | b'\\' | b']' | b'`' | b'{' | b'|' | b'}'
    )
}

/// Escape a URL for use in an `href`/`src` attribute.
pub fn escape_href(s: &str, out: &mut String) {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    for &b in s.as_bytes() {
        if href_safe(b) {
            out.push(b as char);
        } else if b == b'&' {
            out.push_str("&amp;");
        } else if b == b'\'' {
            out.push_str("&#x27;");
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0xf) as usize] as char);
        }
    }
}
