/// A cursor over a single line, tracking the virtual column (tabs expand to
/// multiples of 4).
#[derive(Clone)]
struct Line<'a> {
    text: &'a str,
    pos: usize,     // byte position
    col: usize,     // virtual column
    partial: usize, // spaces remaining from a partially consumed tab
}

impl<'a> Line<'a> {
    fn new(text: &'a str) -> Self {
        Line {
            text,
            pos: 0,
            col: 0,
            partial: 0,
        }
    }

    fn rest(&self) -> &'a str {
        &self.text[self.pos..]
    }

    fn peek(&self) -> Option<u8> {
        if self.partial > 0 {
            return Some(b' ');
        }
        self.text.as_bytes().get(self.pos).copied()
    }

    /// Number of columns of indentation (spaces/tabs) from the current position.
    fn indent(&self) -> usize {
        let mut col = self.col;
        let mut n = self.partial;
        let bytes = self.text.as_bytes();
        let mut p = self.pos;
        if self.partial > 0 {
            col += self.partial;
        }
        while p < bytes.len() {
            match bytes[p] {
                b' ' => {
                    col += 1;
                    n += 1;
                }
                b'\t' => {
                    let adv = 4 - (col % 4);
                    col += adv;
                    n += adv;
                }
                _ => break,
            }
            p += 1;
        }
        n
    }

    fn is_blank(&self) -> bool {
        self.rest().bytes().all(|b| b == b' ' || b == b'\t')
    }

    /// Advance by one byte (non-whitespace or space), updating column.
    fn advance(&mut self, n: usize) {
        for _ in 0..n {
            if self.partial > 0 {
                self.partial -= 1;
                self.col += 1;
                continue;
            }
            match self.text.as_bytes().get(self.pos) {
                Some(b'\t') => {
                    let adv = 4 - (self.col % 4);
                    self.col += adv;
                    self.pos += 1;
                }
                Some(_) => {
                    self.col += 1;
                    self.pos += 1;
                }
                None => {}
            }
        }
    }

    /// Consume up to `n` columns of whitespace.
    fn skip_indent(&mut self, n: usize) -> usize {
        let mut consumed = 0;
        while consumed < n {
            if self.partial > 0 {
                self.partial -= 1;
                self.col += 1;
                consumed += 1;
                continue;
            }
            match self.text.as_bytes().get(self.pos) {
                Some(b' ') => {
                    self.pos += 1;
                    self.col += 1;
                    consumed += 1;
                }
                Some(b'\t') => {
                    let adv = 4 - (self.col % 4);
                    self.pos += 1;
                    if adv > n - consumed {
                        let take = n - consumed;
                        self.partial = adv - take;
                        self.col += take;
                        consumed += take;
                    } else {
                        self.col += adv;
                        consumed += adv;
                    }
                }
                _ => break,
            }
        }
        consumed
    }

    /// Skip all leading whitespace.
    fn skip_ws(&mut self) {
        self.skip_indent(usize::MAX);
    }

    /// The remaining content as a string (with partial tab spaces prepended).
    fn remainder(&self) -> String {
        let mut s = String::new();
        for _ in 0..self.partial {
            s.push(' ');
        }
        s.push_str(self.rest());
        s
    }
}

fn is_ws(b: u8) -> bool {
    b == b' ' || b == b'\t'
}

/// Try to parse an ATX heading from the rest of the line (indent already checked).
fn scan_atx_heading(s: &str) -> Option<(u8, String)> {
    let bytes = s.as_bytes();
    let mut n = 0;
    while n < bytes.len() && bytes[n] == b'#' {
        n += 1;
    }
    if n == 0 || n > 6 {
        return None;
    }
    if n < bytes.len() && !is_ws(bytes[n]) {
        return None;
    }
    let rest = &s[n..];
    let rest = rest.trim_matches(|c| c == ' ' || c == '\t');
    // Remove closing sequence.
    let mut content = rest;
    let trimmed_end = content.trim_end_matches('#');
    if trimmed_end.len() != content.len() {
        if trimmed_end.is_empty() {
            content = "";
        } else if trimmed_end.ends_with(' ') || trimmed_end.ends_with('\t') {
            content = trimmed_end.trim_end_matches(|c| c == ' ' || c == '\t');
        }
    }
    Some((n as u8, content.to_string()))
}

fn scan_thematic_break(s: &str) -> bool {
    let bytes = s.as_bytes();
    let mut c = 0u8;
    let mut count = 0;
    for &b in bytes {
        match b {
            b'*' | b'-' | b'_' => {
                if c == 0 {
                    c = b;
                } else if b != c {
                    return false;
                }
                count += 1;
            }
            b' ' | b'\t' => {}
            _ => return false,
        }
    }
    count >= 3
}

fn scan_setext(s: &str) -> Option<u8> {
    let t = s.trim_end_matches(|c| c == ' ' || c == '\t');
    if t.is_empty() {
        return None;
    }
    if t.bytes().all(|b| b == b'=') {
        Some(1)
    } else if t.bytes().all(|b| b == b'-') {
        Some(2)
    } else {
        None
    }
}

/// Scan a fenced code block opening: returns (fence char, length, info).
fn scan_fence_open(s: &str) -> Option<(u8, usize, String)> {
    let bytes = s.as_bytes();
    let c = *bytes.first()?;
    if c != b'`' && c != b'~' {
        return None;
    }
    let mut n = 0;
    while n < bytes.len() && bytes[n] == c {
        n += 1;
    }
    if n < 3 {
        return None;
    }
    let info = s[n..].trim();
    if c == b'`' && info.contains('`') {
        return None;
    }
    Some((c, n, info.to_string()))
}

fn scan_fence_close(s: &str, fence: u8, len: usize) -> bool {
    let bytes = s.as_bytes();
    let mut n = 0;
    while n < bytes.len() && bytes[n] == fence {
        n += 1;
    }
    n >= len && s[n..].bytes().all(is_ws)
}

const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

fn starts_with_ci(s: &str, prefix: &str) -> bool {
    s.len() >= prefix.len() && s[..prefix.len()].eq_ignore_ascii_case(prefix)
}

/// Determine the HTML block kind started by this line (1..=7), if any.
fn scan_html_block_start(s: &str, can_interrupt_paragraph: bool) -> Option<u8> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'<') {
        return None;
    }
    // Kind 1
    for tag in ["script", "pre", "style", "textarea"] {
        if starts_with_ci(&s[1..], tag) {
            let after = &s[1 + tag.len()..];
            if after.is_empty() || after.starts_with(' ') || after.starts_with('\t') || after.starts_with('>') {
                return Some(1);
            }
        }
    }
    if s.starts_with("<!--") {
        return Some(2);
    }
    if s.starts_with("<?") {
        return Some(3);
    }
    if s.starts_with("<![CDATA[") {
        return Some(5);
    }
    if s.starts_with("<!") && bytes.get(2).map(|b| b.is_ascii_alphabetic()).unwrap_or(false) {
        return Some(4);
    }
    // Kind 6
    {
        let mut p = 1;
        if bytes.get(p) == Some(&b'/') {
            p += 1;
        }
        let start = p;
        while p < bytes.len() && (bytes[p].is_ascii_alphanumeric()) {
            p += 1;
        }
        let name = &s[start..p];
        if !name.is_empty() {
            let lname = name.to_ascii_lowercase();
            if BLOCK_TAGS.contains(&lname.as_str()) {
                let after = &s[p..];
                if after.is_empty()
                    || after.starts_with(' ')
                    || after.starts_with('\t')
                    || after.starts_with('>')
                    || after.starts_with("/>")
                {
                    return Some(6);
                }
            }
        }
    }
    // Kind 7: complete open or closing tag alone on the line.
    if can_interrupt_paragraph {
        return None;
    }
    if let Some(end) = crate::markdown::inline::scan_html_tag(s) {
        // Must not be a kind-1 tag name and the rest must be whitespace.
        if s[end..].bytes().all(is_ws) {
            let inner = &s[1..end];
            let name_start = if inner.starts_with('/') { 1 } else { 0 };
            let name: String = inner[name_start..]
                .chars()
                .take_while(|c| c.is_ascii_alphanumeric() || *c == '-')
                .collect();
            let lname = name.to_ascii_lowercase();
            if ["script", "pre", "style", "textarea"].contains(&lname.as_str()) {
                return None;
            }
            // Only open tags or closing tags (not comments etc.).
            if inner.starts_with('!') || inner.starts_with('?') {
                return None;
            }
            return Some(7);
        }
    }
    None
}

fn html_block_ends(kind: u8, line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    match kind {
        1 => {
            lower.contains("</script>")
                || lower.contains("</pre>")
                || lower.contains("</style>")
                || lower.contains("</textarea>")
        }
        2 => line.contains("-->"),
        3 => line.contains("?>"),
        4 => line.contains('>'),
        5 => line.contains("]]>"),
        _ => false,
    }
}

/// Scan a list marker. Returns (ordered, start, marker char/delim, marker width in columns).
fn scan_list_marker(s: &str) -> Option<(bool, u64, u8, usize)> {
    let bytes = s.as_bytes();
    let first = *bytes.first()?;
    if first == b'-' || first == b'+' || first == b'*' {
        if bytes.len() == 1 || is_ws(bytes[1]) {
            return Some((false, 0, first, 1));
        }
        return None;
    }
    if first.is_ascii_digit() {
        let mut n = 0;
        while n < bytes.len() && bytes[n].is_ascii_digit() && n < 10 {
            n += 1;
        }
        if n > 9 {
            return None;
        }
        if n < bytes.len() && (bytes[n] == b'.' || bytes[n] == b')') {
            if bytes.len() == n + 1 || is_ws(bytes[n + 1]) {
                let start: u64 = s[..n].parse().unwrap_or(0);
                return Some((true, start, bytes[n], n + 1));
            }
        }
    }
    None
}

/// Split a table row into cells (handling `\|` escapes and code spans loosely).
fn split_table_row(s: &str) -> Vec<String> {
    let s = s.trim();
    let bytes = s.as_bytes();
    let mut start = 0;
    let mut end = bytes.len();
    if bytes.first() == Some(&b'|') {
        start = 1;
    }
    if end > start && bytes[end - 1] == b'|' {
        // Make sure the trailing pipe is not escaped.
        let mut bs = 0;
        let mut k = end - 1;
        while k > start && bytes[k - 1] == b'\\' {
            bs += 1;
            k -= 1;
        }
        if bs % 2 == 0 {
            end -= 1;
        }
    }
    let inner = &s[start..end];
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut chars = inner.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if n == '|' {
                    cur.push('|');
                    chars.next();
                    continue;
                }
            }
            cur.push(c);
        } else if c == '|' {
            cells.push(cur.trim().to_string());
            cur = String::new();
        } else {
            cur.push(c);
        }
    }
    cells.push(cur.trim().to_string());
    cells
}

fn scan_table_delimiter(s: &str) -> Option<Vec<Align>> {
    let t = s.trim();
    if !t.contains('-') {
        return None;
    }
    let cells = split_table_row(t);
    // A delimiter row must contain a pipe unless it has only one cell with pipes... require a pipe.
    if !t.contains('|') {
        return None;
    }
    let mut aligns = Vec::new();
    for c in cells {
        let c = c.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let mid = c.trim_start_matches(':').trim_end_matches(':');
        if mid.is_empty() || !mid.bytes().all(|b| b == b'-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            (false, false) => Align::None,
        });
    }
    Some(aligns)
}

pub struct Parser {
    nodes: Vec<Node>,
    refs: HashMap<String, LinkDef>,
    line_number: usize,
}

impl Parser {
    pub fn new() -> Self {
        Parser {
            nodes: vec![Node {
                kind: Kind::Document,
                children: Vec::new(),
                open: true,
                last_line_blank: false,
                parent: None,
            }],
            refs: HashMap::new(),
            line_number: 0,
        }
    }

    fn add_child(&mut self, parent: usize, kind: Kind) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            kind,
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            parent: Some(parent),
        });
        self.nodes[parent].children.push(id);
        id
    }

    fn last_open_child(&self, id: usize) -> Option<usize> {
        let last = *self.nodes[id].children.last()?;
        if self.nodes[last].open {
            Some(last)
        } else {
            None
        }
    }

    fn is_leaf(kind: &Kind) -> bool {
        matches!(
            kind,
            Kind::Paragraph { .. }
                | Kind::Heading { .. }
                | Kind::ThematicBreak
                | Kind::FencedCode { .. }
                | Kind::IndentedCode { .. }
                | Kind::HtmlBlock { .. }
                | Kind::Table { .. }
        )
    }

    /// Close a node and all its open descendants.
    fn finalize(&mut self, id: usize) {
        if !self.nodes[id].open {
            return;
        }
        // Finalize open children first.
        let children = self.nodes[id].children.clone();
        for c in children {
            if self.nodes[c].open {
                self.finalize(c);
            }
        }
        self.nodes[id].open = false;
        // Post-processing.
        let kind = std::mem::replace(&mut self.nodes[id].kind, Kind::ThematicBreak);
        let new_kind = match kind {
            Kind::Paragraph { lines } => {
                let text = lines.join("\n");
                let rest = self.extract_ref_defs(&text);
                if rest.trim().is_empty() {
                    // Remove this node from its parent.
                    let parent = self.nodes[id].parent.unwrap();
                    self.nodes[parent].children.retain(|&c| c != id);
                    Kind::Paragraph { lines: Vec::new() }
                } else {
                    Kind::Paragraph { lines: vec![rest] }
                }
            }
            Kind::List { ordered, start, marker, .. } => {
                let tight = self.compute_tight(id);
                Kind::List {
                    ordered,
                    start,
                    marker,
                    tight,
                }
            }
            other => other,
        };
        self.nodes[id].kind = new_kind;
    }

    fn ends_with_blank_line(&self, mut id: usize) -> bool {
        loop {
            if self.nodes[id].last_line_blank {
                return true;
            }
            match self.nodes[id].kind {
                Kind::List { .. } | Kind::ListItem { .. } => {
                    if let Some(&last) = self.nodes[id].children.last() {
                        id = last;
                    } else {
                        return false;
                    }
                }
                _ => return false,
            }
        }
    }

    fn compute_tight(&self, list: usize) -> bool {
        let items = &self.nodes[list].children;
        for (i, &item) in items.iter().enumerate() {
            let is_last_item = i + 1 == items.len();
            if self.ends_with_blank_line(item) && !is_last_item {
                return false;
            }
            let subs = &self.nodes[item].children;
            for (j, &sub) in subs.iter().enumerate() {
                let is_last_sub = j + 1 == subs.len();
                if self.ends_with_blank_line(sub) && (!is_last_item || !is_last_sub) {
                    return false;
                }
            }
        }
        true
    }

    /// Extract link reference definitions from the start of a paragraph.
    /// Returns the remaining paragraph text.
    fn extract_ref_defs(&mut self, text: &str) -> String {
        let mut rest = text;
        loop {
            match crate::markdown::inline::parse_link_ref_def(rest) {
                Some((label, dest, title, consumed)) => {
                    let key = crate::markdown::inline::normalize_label(&label);
                    self.refs.entry(key).or_insert(LinkDef { dest, title });
                    rest = &rest[consumed..];
                    // Skip the newline following the definition.
                    if rest.starts_with('\n') {
                        rest = &rest[1..];
                    }
                    if rest.is_empty() {
                        return String::new();
                    }
                }
                None => return rest.to_string(),
            }
        }
    }

    pub fn feed_line(&mut self, text: &str) {
        self.line_number += 1;
        let mut line = Line::new(text);
        let mut container = 0usize;
        let mut all_matched = true;

        // 1. Match continuation markers of open blocks.
        loop {
            let child = match self.last_open_child(container) {
                Some(c) => c,
                None => break,
            };
            match &self.nodes[child].kind {
                Kind::BlockQuote => {
                    let mut probe = line.clone();
                    if probe.indent() <= 3 {
                        probe.skip_ws();
                        if probe.peek() == Some(b'>') {
                            probe.advance(1);
                            // Optional following space.
                            if probe.peek() == Some(b' ') || probe.peek() == Some(b'\t') {
                                probe.skip_indent(1);
                            }
                            line = probe;
                            container = child;
                            continue;
                        }
                    }
                    all_matched = false;
                    break;
                }
                Kind::ListItem {
                    content_indent,
                    start_line,
                } => {
                    let ci = *content_indent;
                    let sl = *start_line;
                    if line.is_blank() {
                        if self.nodes[child].children.is_empty() && sl != self.line_number {
                            // An item that began with a blank line cannot continue with another blank.
                            all_matched = false;
                            break;
                        }
                        if self.nodes[child].children.is_empty() && sl == self.line_number {
                            // Same line as marker; handled elsewhere.
                        }
                        container = child;
                        // Consume whatever indentation exists.
                        line.skip_indent(ci);
                        continue;
                    }
                    if line.indent() >= ci {
                        line.skip_indent(ci);
                        container = child;
                        continue;
                    }
                    all_matched = false;
                    break;
                }
                Kind::List { .. } => {
                    // Lists are transparent containers; descend into the last item.
                    container = child;
                    continue;
                }
                _ => break, // leaf
            }
        }

        // The deepest open leaf (if any) under the matched container.
        let leaf = self.last_open_child(container).filter(|&c| Self::is_leaf(&self.nodes[c].kind));

        // 2. Leaf blocks that consume raw lines.
        if let Some(leaf_id) = leaf {
            match &self.nodes[leaf_id].kind {
                Kind::FencedCode { fence, len, indent, .. } => {
                    if all_matched {
                        let fence = *fence;
                        let len = *len;
                        let indent = *indent;
                        let mut probe = line.clone();
                        if probe.indent() <= 3 {
                            probe.skip_ws();
                            if scan_fence_close(probe.rest(), fence, len) {
                                self.finalize(leaf_id);
                                return;
                            }
                        }
                        line.skip_indent(indent);
                        let content = line.remainder();
                        if let Kind::FencedCode { lines, .. } = &mut self.nodes[leaf_id].kind {
                            lines.push(content);
                        }
                        return;
                    }
                }
                Kind::IndentedCode { .. } => {
                    if all_matched {
                        if line.indent() >= 4 {
                            line.skip_indent(4);
                            let content = line.remainder();
                            if let Kind::IndentedCode { lines } = &mut self.nodes[leaf_id].kind {
                                lines.push(content);
                            }
                            return;
                        } else if line.is_blank() {
                            line.skip_indent(4);
                            let content = line.remainder();
                            if let Kind::IndentedCode { lines } = &mut self.nodes[leaf_id].kind {
                                lines.push(content);
                            }
                            self.nodes[leaf_id].last_line_blank = true;
                            return;
                        }
                    }
                    self.finalize(leaf_id);
                }
                Kind::HtmlBlock { kind, .. } => {
                    if all_matched {
                        let kind = *kind;
                        if (kind == 6 || kind == 7) && line.is_blank() {
                            self.finalize(leaf_id);
                            // Fall through: blank line handling.
                        } else {
                            let content = line.remainder();
                            let ends = html_block_ends(kind, &content);
                            if let Kind::HtmlBlock { lines, .. } = &mut self.nodes[leaf_id].kind {
                                lines.push(content);
                            }
                            if ends {
                                self.finalize(leaf_id);
                            }
                            return;
                        }
                    } else if !line.is_blank() {
                        // Not all matched: html block can't lazily continue.
                        self.finalize(leaf_id);
                    }
                }
                _ => {}
            }
        }

        // 3. Look for new block starts.
        let mut leaf = self.last_open_child(container).filter(|&c| Self::is_leaf(&self.nodes[c].kind));
        let has_open_paragraph = |p: &Parser, leaf: Option<usize>| {
            leaf.map(|l| matches!(p.nodes[l].kind, Kind::Paragraph { .. })).unwrap_or(false)
        };
        let mut opened_new = false;

        loop {
            let indent = line.indent();
            let blank = line.is_blank();
            if blank {
                break;
            }
            let paragraph_open = has_open_paragraph(self, leaf);
            // Lazy continuation candidate: deepest open paragraph anywhere below container.
            if indent >= 4 {
                if paragraph_open || (!all_matched && self.deepest_open_paragraph(container).is_some()) {
                    break; // paragraph continuation
                }
                // Indented code block.
                self.close_unmatched(container);
                line.skip_indent(4);
                let content = line.remainder();
                let id = self.add_child(container, Kind::IndentedCode { lines: vec![content] });
                let _ = id;
                return;
            }
            let mut probe = line.clone();
            probe.skip_ws();
            let rest = probe.rest();
            let first = match rest.bytes().next() {
                Some(b) => b,
                None => break,
            };

            // Block quote.
            if first == b'>' {
                self.close_unmatched(container);
                probe.advance(1);
                if probe.peek() == Some(b' ') || probe.peek() == Some(b'\t') {
                    probe.skip_indent(1);
                }
                line = probe;
                container = self.add_child(container, Kind::BlockQuote);
                all_matched = true;
                opened_new = true;
                leaf = None;
                continue;
            }
            // ATX heading.
            if first == b'#' {
                if let Some((level, text)) = scan_atx_heading(rest) {
                    self.close_unmatched(container);
                    let id = self.add_child(container, Kind::Heading { level, text });
                    self.nodes[id].open = false;
                    return;
                }
            }
            // Fenced code.
            if first == b'`' || first == b'~' {
                if let Some((fence, len, info)) = scan_fence_open(rest) {
                    self.close_unmatched(container);
                    self.add_child(
                        container,
                        Kind::FencedCode {
                            fence,
                            len,
                            indent,
                            info,
                            lines: Vec::new(),
                        },
                    );
                    return;
                }
            }
            // HTML block.
            if first == b'<' {
                let para = paragraph_open || (!all_matched && self.deepest_open_paragraph(container).is_some());
                if let Some(kind) = scan_html_block_start(rest, para) {
                    self.close_unmatched(container);
                    let content = line.remainder();
                    let ends = html_block_ends(kind, &content);
                    let id = self.add_child(
                        container,
                        Kind::HtmlBlock {
                            kind,
                            lines: vec![content],
                        },
                    );
                    if ends {
                        self.finalize(id);
                    }
                    return;
                }
            }
            // Setext heading underline.
            if paragraph_open && all_matched && !opened_new {
                if let Some(level) = scan_setext(rest) {
                    let leaf_id = leaf.unwrap();
                    if let Kind::Paragraph { lines } = &self.nodes[leaf_id].kind {
                        let text = lines.join("\n");
                        // Reference definitions at the start are extracted first.
                        let remaining = self.extract_ref_defs(&text);
                        if remaining.trim().is_empty() {
                            // Paragraph consisted only of ref defs: the underline is a
                            // thematic break or paragraph.
                            let parent = self.nodes[leaf_id].parent.unwrap();
                            self.nodes[leaf_id].open = false;
                            self.nodes[parent].children.retain(|&c| c != leaf_id);
                            leaf = None;
                            if scan_thematic_break(rest) {
                                let id = self.add_child(container, Kind::ThematicBreak);
                                self.nodes[id].open = false;
                                return;
                            }
                            // Fall through to paragraph creation with this line.
                            break;
                        }
                        self.nodes[leaf_id].kind = Kind::Heading {
                            level,
                            text: remaining.trim_end().to_string(),
                        };
                        self.nodes[leaf_id].open = false;
                        return;
                    }
                }
            }
            // Thematic break.
            if (first == b'*' || first == b'-' || first == b'_') && scan_thematic_break(rest) {
                self.close_unmatched(container);
                let id = self.add_child(container, Kind::ThematicBreak);
                self.nodes[id].open = false;
                return;
            }
            // List item.
            if let Some((ordered, start, marker, width)) = scan_list_marker(rest) {
                let para = paragraph_open || (!all_matched && self.deepest_open_paragraph(container).is_some());
                let mut after = probe.clone();
                after.advance(width);
                let rest_blank = after.is_blank();
                // Interrupting a paragraph: ordered lists must start at 1, item must be non-empty.
                if para && (rest_blank || (ordered && start != 1)) {
                    // Not a list start.
                } else {
                    self.close_unmatched(container);
                    // Determine content indent.
                    let spaces = after.indent();
                    let content_indent;
                    if rest_blank {
                        content_indent = width + 1;
                        after.skip_ws();
                    } else if spaces >= 5 || spaces == 0 {
                        content_indent = width + 1;
                        after.skip_indent(1);
                    } else {
                        content_indent = width + spaces;
                        after.skip_indent(spaces);
                    }
                    let content_indent = content_indent + indent;
                    // Find or create the list.
                    let list = match self.last_open_child(container) {
                        Some(l)
                            if matches!(
                                &self.nodes[l].kind,
                                Kind::List { ordered: o, marker: m, .. } if *o == ordered && *m == marker
                            ) =>
                        {
                            l
                        }
                        _ => {
                            if let Some(l) = self.last_open_child(container) {
                                self.finalize(l);
                            }
                            self.add_child(
                                container,
                                Kind::List {
                                    ordered,
                                    start,
                                    marker,
                                    tight: true,
                                },
                            )
                        }
                    };
                    let item = self.add_child(
                        list,
                        Kind::ListItem {
                            content_indent,
                            start_line: self.line_number,
                        },
                    );
                    line = after;
                    container = item;
                    all_matched = true;
                    opened_new = true;
                    leaf = None;
                    continue;
                }
            }
            // Table: paragraph with a single line followed by a delimiter row.
            if paragraph_open && all_matched && !opened_new {
                let leaf_id = leaf.unwrap();
                if let Kind::Paragraph { lines } = &self.nodes[leaf_id].kind {
                    if lines.len() == 1 && lines[0].contains('|') {
                        if let Some(aligns) = scan_table_delimiter(rest) {
                            let head = split_table_row(&lines[0]);
                            if head.len() == aligns.len() {
                                self.nodes[leaf_id].kind = Kind::Table {
                                    aligns,
                                    head,
                                    rows: Vec::new(),
                                };
                                return;
                            }
                        }
                    }
                }
            }
            break;
        }

        // 4. Add the remaining text.
        let blank = line.is_blank();
        let leaf = self.last_open_child(container).filter(|&c| Self::is_leaf(&self.nodes[c].kind));

        if blank {
            if let Some(leaf_id) = leaf {
                match self.nodes[leaf_id].kind {
                    Kind::Paragraph { .. } | Kind::Table { .. } => self.finalize(leaf_id),
                    _ => {}
                }
            }
            if !all_matched {
                self.close_unmatched(container);
            }
            // Record blank line for list tightness.
            let is_empty_item_start = matches!(
                self.nodes[container].kind,
                Kind::ListItem { start_line, .. } if start_line == self.line_number
            ) && self.nodes[container].children.is_empty();
            let last_line_blank = !matches!(self.nodes[container].kind, Kind::BlockQuote)
                && !matches!(self.nodes[container].kind, Kind::FencedCode { .. })
                && !is_empty_item_start;
            self.nodes[container].last_line_blank = last_line_blank;
            let mut p = self.nodes[container].parent;
            while let Some(pid) = p {
                self.nodes[pid].last_line_blank = false;
                p = self.nodes[pid].parent;
            }
            return;
        }

        // Non-blank text.
        let content = line.remainder();
        if let Some(leaf_id) = leaf {
            if all_matched {
                match &mut self.nodes[leaf_id].kind {
                    Kind::Paragraph { lines } => {
                        lines.push(content.trim_start_matches(|c| c == ' ' || c == '\t').to_string());
                        self.clear_blank_flags(container);
                        return;
                    }
                    Kind::Table { rows, aligns, .. } => {
                        let mut cells = split_table_row(&content);
                        let n = aligns.len();
                        cells.truncate(n);
                        while cells.len() < n {
                            cells.push(String::new());
                        }
                        rows.push(cells);
                        self.clear_blank_flags(container);
                        return;
                    }
                    _ => {}
                }
            }
        }
        // Lazy continuation.
        if !all_matched {
            if let Some(pid) = self.deepest_open_paragraph(container) {
                if let Kind::Paragraph { lines } = &mut self.nodes[pid].kind {
                    lines.push(content.trim_start_matches(|c| c == ' ' || c == '\t').to_string());
                }
                return;
            }
            self.close_unmatched(container);
        }
        if let Some(leaf_id) = self.last_open_child(container) {
            self.finalize(leaf_id);
        }
        self.add_child(
            container,
            Kind::Paragraph {
                lines: vec![content.trim_start_matches(|c| c == ' ' || c == '\t').to_string()],
            },
        );
        self.clear_blank_flags(container);
    }

    fn clear_blank_flags(&mut self, mut id: usize) {
        loop {
            self.nodes[id].last_line_blank = false;
            match self.nodes[id].parent {
                Some(p) => id = p,
                None => break,
            }
        }
    }

    /// Find the deepest open paragraph along the last-child chain below `container`.
    fn deepest_open_paragraph(&self, mut id: usize) -> Option<usize> {
        loop {
            let child = self.last_open_child(id)?;
            match self.nodes[child].kind {
                Kind::Paragraph { .. } => return Some(child),
                Kind::BlockQuote | Kind::List { .. } | Kind::ListItem { .. } => id = child,
                _ => return None,
            }
        }
    }

    /// Close any open children of `container` (unmatched blocks).
    fn close_unmatched(&mut self, container: usize) {
        if let Some(child) = self.last_open_child(container) {
            self.finalize(child);
        }
    }

    pub fn finish(mut self) -> Document {
        self.finalize(0);
        let blocks = self.collect(0);
        Document {
            blocks,
            refs: self.refs,
        }
    }

    fn collect(&self, id: usize) -> Vec<Block> {
        let mut out = Vec::new();
        for &c in &self.nodes[id].children {
            if let Some(b) = self.to_block(c) {
                out.push(b);
            }
        }
        out
    }

    fn to_block(&self, id: usize) -> Option<Block> {
        let node = &self.nodes[id];
        Some(match &node.kind {
            Kind::Document => return None,
            Kind::BlockQuote => Block::BlockQuote(self.collect(id)),
            Kind::List {
                ordered, start, tight, ..
            } => Block::List {
                ordered: *ordered,
                start: *start,
                tight: *tight,
                items: node.children.iter().map(|&c| self.collect(c)).collect(),
            },
            Kind::ListItem { .. } => return None,
            Kind::Paragraph { lines } => {
                if lines.is_empty() {
                    return None;
                }
                let text = lines.join("\n");
                let text = text.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\n');
                Block::Paragraph(text.to_string())
            }
            Kind::Heading { level, text } => Block::Heading {
                level: *level,
                text: text.clone(),
            },
            Kind::ThematicBreak => Block::ThematicBreak,
            Kind::FencedCode { info, lines, .. } => {
                let mut text = lines.join("\n");
                if !lines.is_empty() {
                    text.push('\n');
                }
                Block::CodeBlock {
                    info: if info.is_empty() { None } else { Some(info.clone()) },
                    text,
                }
            }
            Kind::IndentedCode { lines } => {
                // Strip trailing blank lines.
                let mut ls: Vec<&String> = lines.iter().collect();
                while let Some(last) = ls.last() {
                    if last.trim().is_empty() {
                        ls.pop();
                    } else {
                        break;
                    }
                }
                let mut text = ls.iter().map(|s| s.as_str()).collect::<Vec<_>>().join("\n");
                if !ls.is_empty() {
                    text.push('\n');
                }
                Block::CodeBlock { info: None, text }
            }
            Kind::HtmlBlock { lines, .. } => {
                let mut text = lines.join("\n");
                text.push('\n');
                Block::HtmlBlock(text)
            }
            Kind::Table { aligns, head, rows } => Block::Table {
                aligns: aligns.clone(),
                head: head.clone(),
                rows: rows.clone(),
            },
        })
    }
}

pub fn parse_blocks(text: &str) -> Document {
    let mut parser = Parser::new();
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        parser.feed_line(line);
    }
    parser.finish()
}
