//! Inline-level Markdown parsing.

use crate::entities;
use std::collections::HashMap;

use super::block::LinkDef;

#[derive(Debug, Clone)]
pub enum Inline {
    Text(String),
    Code(String),
    Math { display: bool, text: String },
    Html(String),
    SoftBreak,
    HardBreak,
    Emph(Vec<Inline>),
    Strong(Vec<Inline>),
    Link {
        dest: String,
        title: Option<String>,
        children: Vec<Inline>,
    },
    Image {
        dest: String,
        title: Option<String>,
        children: Vec<Inline>,
    },
}

#[derive(Debug)]
enum Item {
    Node(Inline),
    Delim {
        ch: u8,
        orig: usize,
        count: usize,
        can_open: bool,
        can_close: bool,
    },
    Bracket {
        is_image: bool,
        active: bool,
        /// Byte offset in the source just after the bracket.
        src_pos: usize,
    },
}

fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation() || (!c.is_ascii() && !c.is_alphanumeric() && !c.is_whitespace())
}

fn is_unicode_ws(c: char) -> bool {
    c.is_whitespace()
}

/// Decode an entity at `s[pos..]` (which starts with `&`). Returns (decoded, consumed).
pub fn scan_entity(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'&') {
        return None;
    }
    if bytes.get(1) == Some(&b'#') {
        let (radix, start) = if matches!(bytes.get(2), Some(b'x') | Some(b'X')) {
            (16, 3)
        } else {
            (10, 2)
        };
        let mut p = start;
        while p < bytes.len() && (bytes[p] as char).is_digit(radix) {
            p += 1;
        }
        let ndigits = p - start;
        if ndigits == 0 || (radix == 10 && ndigits > 7) || (radix == 16 && ndigits > 6) {
            return None;
        }
        if bytes.get(p) != Some(&b';') {
            return None;
        }
        let num = u32::from_str_radix(&s[start..p], radix).unwrap_or(0);
        let c = if num == 0 {
            '\u{FFFD}'
        } else {
            char::from_u32(num).unwrap_or('\u{FFFD}')
        };
        return Some((c.to_string(), p + 1));
    }
    let mut p = 1;
    while p < bytes.len() && bytes[p].is_ascii_alphanumeric() {
        p += 1;
    }
    if p == 1 || bytes.get(p) != Some(&b';') {
        return None;
    }
    let name = &s[1..p];
    entities::lookup(name).map(|v| (v.to_string(), p + 1))
}

/// Process backslash escapes and entities in a string (used for link
/// destinations, titles, and code block info strings).
pub fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'\\' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
            out.push(bytes[i + 1] as char);
            i += 2;
        } else if b == b'&' {
            if let Some((dec, n)) = scan_entity(&s[i..]) {
                out.push_str(&dec);
                i += n;
            } else {
                out.push('&');
                i += 1;
            }
        } else {
            // Push the full UTF-8 char.
            let ch = s[i..].chars().next().unwrap();
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

pub fn normalize_label(label: &str) -> String {
    let mut out = String::new();
    let mut prev_ws = false;
    for c in label.trim().chars() {
        if c.is_whitespace() {
            if !prev_ws {
                out.push(' ');
            }
            prev_ws = true;
        } else {
            for lc in c.to_lowercase() {
                out.push(lc);
            }
            prev_ws = false;
        }
    }
    out
}

/// Scan an HTML tag (open, close, comment, PI, declaration, CDATA) at the
/// start of `s` (which begins with `<`). Returns the end offset.
pub fn scan_html_tag(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'<') {
        return None;
    }
    if s.starts_with("<!--") {
        // Comment.
        let rest = &s[4..];
        if rest.starts_with('>') {
            return Some(5);
        }
        if rest.starts_with("->") {
            return Some(6);
        }
        let end = rest.find("-->")?;
        return Some(4 + end + 3);
    }
    if s.starts_with("<?") {
        let end = s[2..].find("?>")?;
        return Some(2 + end + 2);
    }
    if s.starts_with("<![CDATA[") {
        let end = s[9..].find("]]>")?;
        return Some(9 + end + 3);
    }
    if s.starts_with("<!") {
        if bytes.get(2).map(|b| b.is_ascii_alphabetic()).unwrap_or(false) {
            let end = s[2..].find('>')?;
            return Some(2 + end + 1);
        }
        return None;
    }
    let mut p = 1;
    let closing = bytes.get(p) == Some(&b'/');
    if closing {
        p += 1;
    }
    // Tag name.
    if !bytes.get(p).map(|b| b.is_ascii_alphabetic()).unwrap_or(false) {
        return None;
    }
    p += 1;
    while p < bytes.len() && (bytes[p].is_ascii_alphanumeric() || bytes[p] == b'-') {
        p += 1;
    }
    if closing {
        // Optional whitespace then '>'.
        while p < bytes.len() && (bytes[p] as char).is_whitespace() {
            p += 1;
        }
        if bytes.get(p) == Some(&b'>') {
            return Some(p + 1);
        }
        return None;
    }
    // Attributes.
    loop {
        // Whitespace.
        let ws_start = p;
        while p < bytes.len() && (bytes[p] as char).is_whitespace() {
            p += 1;
        }
        if p >= bytes.len() {
            return None;
        }
        if bytes[p] == b'>' {
            return Some(p + 1);
        }
        if bytes[p] == b'/' {
            if bytes.get(p + 1) == Some(&b'>') {
                return Some(p + 2);
            }
            return None;
        }
        if p == ws_start {
            // Attribute must be preceded by whitespace.
            return None;
        }
        // Attribute name.
        if !(bytes[p].is_ascii_alphabetic() || bytes[p] == b'_' || bytes[p] == b':') {
            return None;
        }
        p += 1;
        while p < bytes.len()
            && (bytes[p].is_ascii_alphanumeric()
                || bytes[p] == b'_'
                || bytes[p] == b'.'
                || bytes[p] == b':'
                || bytes[p] == b'-')
        {
            p += 1;
        }
        // Optional value.
        let mut q = p;
        while q < bytes.len() && (bytes[q] as char).is_whitespace() {
            q += 1;
        }
        if bytes.get(q) == Some(&b'=') {
            q += 1;
            while q < bytes.len() && (bytes[q] as char).is_whitespace() {
                q += 1;
            }
            match bytes.get(q) {
                Some(b'"') => {
                    let end = s[q + 1..].find('"')?;
                    p = q + 1 + end + 1;
                }
                Some(b'\'') => {
                    let end = s[q + 1..].find('\'')?;
                    p = q + 1 + end + 1;
                }
                Some(_) => {
                    let start = q;
                    while q < bytes.len()
                        && !(bytes[q] as char).is_whitespace()
                        && !matches!(bytes[q], b'"' | b'\'' | b'=' | b'<' | b'>' | b'`')
                    {
                        q += 1;
                    }
                    if q == start {
                        return None;
                    }
                    p = q;
                }
                None => return None,
            }
        }
    }
}

fn scan_autolink(s: &str) -> Option<(String, String, usize)> {
    // Returns (href, text, consumed). `s` starts with '<'.
    let bytes = s.as_bytes();
    let end = s.find('>')?;
    let inner = &s[1..end];
    if inner.is_empty() {
        return None;
    }
    // URI autolink.
    if let Some(colon) = inner.find(':') {
        let scheme = &inner[..colon];
        let sb = scheme.as_bytes();
        if sb.len() >= 2
            && sb.len() <= 32
            && sb[0].is_ascii_alphabetic()
            && sb.iter().all(|b| b.is_ascii_alphanumeric() || *b == b'+' || *b == b'.' || *b == b'-')
        {
            let rest = &inner[colon + 1..];
            if !rest.bytes().any(|b| b <= b' ' || b == b'<' || b == b'>') {
                return Some((inner.to_string(), inner.to_string(), end + 1));
            }
        }
    }
    // Email autolink.
    if let Some(at) = inner.find('@') {
        let local = &inner[..at];
        let domain = &inner[at + 1..];
        let local_ok = !local.is_empty()
            && local.bytes().all(|b| {
                b.is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&b)
            });
        let domain_ok = !domain.is_empty()
            && domain.split('.').all(|part| {
                !part.is_empty()
                    && part.len() <= 63
                    && part.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
                    && !part.starts_with('-')
                    && !part.ends_with('-')
            });
        if local_ok && domain_ok {
            return Some((format!("mailto:{}", inner), inner.to_string(), end + 1));
        }
    }
    let _ = bytes;
    None
}

/// Parse a link label `[...]` at the start of `s`. Returns (raw label, consumed).
fn scan_link_label(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'[') {
        return None;
    }
    let mut i = 1;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 2,
            b'[' => return None,
            b']' => {
                let label = &s[1..i];
                if label.chars().count() > 999 {
                    return None;
                }
                return Some((label.to_string(), i + 1));
            }
            _ => i += 1,
        }
    }
    None
}

/// Parse a link destination at the start of `s`. Returns (dest raw, consumed).
fn scan_link_dest(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() == Some(&b'<') {
        let mut i = 1;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' => i += 2,
                b'\n' | b'<' => return None,
                b'>' => return Some((s[1..i].to_string(), i + 1)),
                _ => i += 1,
            }
        }
        return None;
    }
    let mut depth = 0i32;
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'\\' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if b <= b' ' || b == 0x7f {
            break;
        }
        if b == b'(' {
            depth += 1;
            if depth > 32 {
                return None;
            }
        } else if b == b')' {
            if depth == 0 {
                break;
            }
            depth -= 1;
        }
        i += 1;
    }
    if depth != 0 {
        return None;
    }
    Some((s[..i].to_string(), i))
}

/// Parse a link title at the start of `s`. Returns (title raw, consumed).
fn scan_link_title(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    let open = *bytes.first()?;
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut i = 1;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => i += 2,
            b if b == close => return Some((s[1..i].to_string(), i + 1)),
            b'(' if open == b'(' => return None,
            b'\n' => {
                // No blank lines allowed.
                if s[i + 1..].trim_start_matches(|c| c == ' ' || c == '\t').starts_with('\n') {
                    return None;
                }
                i += 1;
            }
            _ => i += 1,
        }
    }
    None
}

fn skip_ws_nl(s: &str, mut i: usize) -> usize {
    let bytes = s.as_bytes();
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n') {
        i += 1;
    }
    i
}

/// Parse a link reference definition at the start of `s`.
/// Returns (label, dest, title, consumed bytes up to end of line (not including newline)).
pub fn parse_link_ref_def(s: &str) -> Option<(String, String, Option<String>, usize)> {
    // Up to 3 spaces of indentation.
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() && i < 3 && bytes[i] == b' ' {
        i += 1;
    }
    let (label, n) = scan_link_label(&s[i..])?;
    if label.trim().is_empty() {
        return None;
    }
    i += n;
    if bytes.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    i = skip_ws_nl(s, i);
    let (dest, n) = scan_link_dest(&s[i..])?;
    if dest.is_empty() && !s[i..].starts_with('<') {
        return None;
    }
    i += n;
    // Title (optional), must be preceded by whitespace.
    let after_dest = i;
    let j = skip_ws_nl(s, i);
    let mut title = None;
    let mut end = after_dest;
    if j > after_dest {
        if let Some((t, n)) = scan_link_title(&s[j..]) {
            let k = j + n;
            // Rest of line must be blank.
            let mut m = k;
            while m < bytes.len() && (bytes[m] == b' ' || bytes[m] == b'\t') {
                m += 1;
            }
            if m >= bytes.len() || bytes[m] == b'\n' {
                title = Some(unescape(&t));
                end = m;
            } else {
                // Title invalid: the dest line must end here on its own.
                title = None;
                end = after_dest;
            }
        }
    }
    if title.is_none() {
        // Rest of the dest line must be blank.
        let mut m = after_dest;
        while m < bytes.len() && (bytes[m] == b' ' || bytes[m] == b'\t') {
            m += 1;
        }
        if m < bytes.len() && bytes[m] != b'\n' {
            return None;
        }
        end = m;
    }
    Some((label, unescape(&dest), title, end))
}

pub struct InlineParser<'a> {
    src: &'a str,
    refs: &'a HashMap<String, LinkDef>,
}

impl<'a> InlineParser<'a> {
    pub fn new(src: &'a str, refs: &'a HashMap<String, LinkDef>) -> Self {
        InlineParser { src, refs }
    }

    pub fn parse(&self) -> Vec<Inline> {
        let mut items: Vec<Item> = Vec::new();
        let s = self.src;
        let bytes = s.as_bytes();
        let mut i = 0;
        let mut text = String::new();

        macro_rules! flush {
            () => {
                if !text.is_empty() {
                    items.push(Item::Node(Inline::Text(std::mem::take(&mut text))));
                }
            };
        }

        while i < bytes.len() {
            let b = bytes[i];
            match b {
                b'\\' => {
                    if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                        flush!();
                        items.push(Item::Node(Inline::HardBreak));
                        i += 2;
                        // Skip leading spaces on the next line.
                        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
                            i += 1;
                        }
                    } else if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
                        text.push(bytes[i + 1] as char);
                        i += 2;
                    } else {
                        text.push('\\');
                        i += 1;
                    }
                }
                b'`' => {
                    let mut n = 0;
                    while i + n < bytes.len() && bytes[i + n] == b'`' {
                        n += 1;
                    }
                    // Find closing run of the same length.
                    let mut j = i + n;
                    let mut found = None;
                    while j < bytes.len() {
                        if bytes[j] == b'`' {
                            let mut m = 0;
                            while j + m < bytes.len() && bytes[j + m] == b'`' {
                                m += 1;
                            }
                            if m == n {
                                found = Some(j);
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                    match found {
                        Some(j) => {
                            flush!();
                            let content = &s[i + n..j];
                            let mut c: String = content.replace('\n', " ");
                            if c.len() >= 2
                                && c.starts_with(' ')
                                && c.ends_with(' ')
                                && !c.bytes().all(|b| b == b' ')
                            {
                                c = c[1..c.len() - 1].to_string();
                            }
                            items.push(Item::Node(Inline::Code(c)));
                            i = j + n;
                        }
                        None => {
                            text.push_str(&s[i..i + n]);
                            i += n;
                        }
                    }
                }
                b'$' => {
                    let display = i + 1 < bytes.len() && bytes[i + 1] == b'$';
                    if display {
                        // Search for the next unescaped '$'; it must be '$$'.
                        let mut j = i + 2;
                        let mut found = None;
                        while j < bytes.len() {
                            match bytes[j] {
                                b'\\' => j += 2,
                                b'$' => {
                                    if j + 1 < bytes.len() && bytes[j + 1] == b'$' {
                                        found = Some(j);
                                    }
                                    break;
                                }
                                _ => j += 1,
                            }
                        }
                        match found {
                            Some(j) => {
                                flush!();
                                items.push(Item::Node(Inline::Math {
                                    display: true,
                                    text: s[i + 2..j].to_string(),
                                }));
                                i = j + 2;
                            }
                            None => {
                                text.push('$');
                                i += 1;
                            }
                        }
                    } else {
                        // Inline math: next char must exist and not be whitespace.
                        let next_ok = s[i + 1..]
                            .chars()
                            .next()
                            .map(|c| !c.is_whitespace())
                            .unwrap_or(false);
                        let mut matched = false;
                        if next_ok {
                            let mut j = i + 1;
                            while j < bytes.len() {
                                match bytes[j] {
                                    b'\\' => j += 2,
                                    b'$' => break,
                                    _ => j += 1,
                                }
                            }
                            if j < bytes.len() && bytes[j] == b'$' {
                                let prev = s[..j].chars().last().unwrap();
                                if !prev.is_whitespace() {
                                    flush!();
                                    items.push(Item::Node(Inline::Math {
                                        display: false,
                                        text: s[i + 1..j].to_string(),
                                    }));
                                    i = j + 1;
                                    matched = true;
                                }
                            }
                        }
                        if !matched {
                            text.push('$');
                            i += 1;
                        }
                    }
                }
                b'*' | b'_' => {
                    let mut n = 0;
                    while i + n < bytes.len() && bytes[i + n] == b {
                        n += 1;
                    }
                    let prev = s[..i].chars().last();
                    let next = s[i + n..].chars().next();
                    let prev_ws = prev.map(is_unicode_ws).unwrap_or(true);
                    let next_ws = next.map(is_unicode_ws).unwrap_or(true);
                    let prev_punct = prev.map(is_punct).unwrap_or(false);
                    let next_punct = next.map(is_punct).unwrap_or(false);
                    let left_flanking = !next_ws && (!next_punct || prev_ws || prev_punct);
                    let right_flanking = !prev_ws && (!prev_punct || next_ws || next_punct);
                    let (can_open, can_close) = if b == b'*' {
                        (left_flanking, right_flanking)
                    } else {
                        (
                            left_flanking && (!right_flanking || prev_punct),
                            right_flanking && (!left_flanking || next_punct),
                        )
                    };
                    flush!();
                    items.push(Item::Delim {
                        ch: b,
                        orig: n,
                        count: n,
                        can_open,
                        can_close,
                    });
                    i += n;
                }
                b'[' => {
                    flush!();
                    items.push(Item::Bracket {
                        is_image: false,
                        active: true,
                        src_pos: i + 1,
                    });
                    i += 1;
                }
                b'!' if i + 1 < bytes.len() && bytes[i + 1] == b'[' => {
                    flush!();
                    items.push(Item::Bracket {
                        is_image: true,
                        active: true,
                        src_pos: i + 2,
                    });
                    i += 2;
                }
                b']' => {
                    flush!();
                    // Find the nearest opener.
                    let opener_idx = items.iter().rposition(|it| matches!(it, Item::Bracket { .. }));
                    match opener_idx {
                        None => {
                            text.push(']');
                            i += 1;
                        }
                        Some(oi) => {
                            let (is_image, active, src_pos) = match &items[oi] {
                                Item::Bracket {
                                    is_image,
                                    active,
                                    src_pos,
                                } => (*is_image, *active, *src_pos),
                                _ => unreachable!(),
                            };
                            if !active {
                                items[oi] = Item::Node(Inline::Text(
                                    if is_image { "![" } else { "[" }.to_string(),
                                ));
                                text.push(']');
                                i += 1;
                                continue;
                            }
                            // Try to parse link syntax after ']'.
                            let after = i + 1;
                            let mut result: Option<(String, Option<String>, usize)> = None;
                            // Inline link.
                            if bytes.get(after) == Some(&b'(') {
                                let mut j = skip_ws_nl(s, after + 1);
                                if bytes.get(j) == Some(&b')') {
                                    result = Some((String::new(), None, j + 1));
                                } else if let Some((dest, n)) = scan_link_dest(&s[j..]) {
                                    j += n;
                                    let k = skip_ws_nl(s, j);
                                    let mut title = None;
                                    let mut ok = false;
                                    let mut endpos = k;
                                    if bytes.get(k) == Some(&b')') {
                                        ok = true;
                                        endpos = k + 1;
                                    } else if k > j {
                                        if let Some((t, n)) = scan_link_title(&s[k..]) {
                                            let m = skip_ws_nl(s, k + n);
                                            if bytes.get(m) == Some(&b')') {
                                                title = Some(unescape(&t));
                                                ok = true;
                                                endpos = m + 1;
                                            }
                                        }
                                    }
                                    if ok {
                                        result = Some((unescape(&dest), title, endpos));
                                    }
                                }
                            }
                            // Reference link.
                            if result.is_none() {
                                let raw_label = &s[src_pos..i];
                                let mut consumed_end = after;
                                let mut label: Option<String> = None;
                                if bytes.get(after) == Some(&b'[') {
                                    if let Some((l, n)) = scan_link_label(&s[after..]) {
                                        if l.trim().is_empty() {
                                            // Collapsed reference.
                                            label = Some(raw_label.to_string());
                                            consumed_end = after + n;
                                        } else {
                                            label = Some(l);
                                            consumed_end = after + n;
                                        }
                                    } else {
                                        label = Some(raw_label.to_string());
                                    }
                                } else {
                                    label = Some(raw_label.to_string());
                                }
                                if let Some(l) = label {
                                    if !l.trim().is_empty() && !l.contains('[') && !l.contains(']') {
                                        let key = normalize_label(&l);
                                        if let Some(def) = self.refs.get(&key) {
                                            result =
                                                Some((def.dest.clone(), def.title.clone(), consumed_end));
                                        }
                                    } else if l.trim().is_empty() {
                                        // not a valid label
                                    }
                                }
                            }
                            match result {
                                Some((dest, title, endpos)) => {
                                    // Build children from items after the opener.
                                    let mut children_items: Vec<Item> = items.drain(oi + 1..).collect();
                                    items.pop(); // remove the opener
                                    process_emphasis(&mut children_items);
                                    let children = items_to_inlines(children_items);
                                    let node = if is_image {
                                        Inline::Image {
                                            dest,
                                            title,
                                            children,
                                        }
                                    } else {
                                        Inline::Link {
                                            dest,
                                            title,
                                            children,
                                        }
                                    };
                                    items.push(Item::Node(node));
                                    if !is_image {
                                        for it in items.iter_mut() {
                                            if let Item::Bracket {
                                                is_image: false,
                                                active,
                                                ..
                                            } = it
                                            {
                                                *active = false;
                                            }
                                        }
                                    }
                                    i = endpos;
                                }
                                None => {
                                    items[oi] = Item::Node(Inline::Text(
                                        if is_image { "![" } else { "[" }.to_string(),
                                    ));
                                    text.push(']');
                                    i += 1;
                                }
                            }
                        }
                    }
                }
                b'<' => {
                    if let Some((href, txt, n)) = scan_autolink(&s[i..]) {
                        flush!();
                        items.push(Item::Node(Inline::Link {
                            dest: href,
                            title: None,
                            children: vec![Inline::Text(txt)],
                        }));
                        i += n;
                    } else if let Some(n) = scan_html_tag(&s[i..]) {
                        flush!();
                        items.push(Item::Node(Inline::Html(s[i..i + n].to_string())));
                        i += n;
                    } else {
                        text.push('<');
                        i += 1;
                    }
                }
                b'&' => {
                    if let Some((dec, n)) = scan_entity(&s[i..]) {
                        text.push_str(&dec);
                        i += n;
                    } else {
                        text.push('&');
                        i += 1;
                    }
                }
                b'\n' => {
                    // Hard break if preceded by two or more spaces.
                    let trailing = text.len() - text.trim_end_matches(' ').len();
                    let trimmed_len = text.trim_end_matches(' ').len();
                    text.truncate(trimmed_len);
                    flush!();
                    if trailing >= 2 {
                        items.push(Item::Node(Inline::HardBreak));
                    } else {
                        items.push(Item::Node(Inline::SoftBreak));
                    }
                    i += 1;
                    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
                        i += 1;
                    }
                }
                _ => {
                    let ch = s[i..].chars().next().unwrap();
                    text.push(ch);
                    i += ch.len_utf8();
                }
            }
        }
        flush!();
        process_emphasis(&mut items);
        items_to_inlines(items)
    }
}

fn items_to_inlines(items: Vec<Item>) -> Vec<Inline> {
    let mut out: Vec<Inline> = Vec::new();
    for it in items {
        let node = match it {
            Item::Node(n) => n,
            Item::Delim { ch, count, .. } => {
                Inline::Text(std::iter::repeat(ch as char).take(count).collect())
            }
            Item::Bracket { is_image, .. } => {
                Inline::Text(if is_image { "![".to_string() } else { "[".to_string() })
            }
        };
        // Merge adjacent text nodes.
        if let (Some(Inline::Text(prev)), Inline::Text(t)) = (out.last_mut(), &node) {
            prev.push_str(t);
            continue;
        }
        out.push(node);
    }
    out
}

fn process_emphasis(items: &mut Vec<Item>) {
    let mut closer = 0;
    while closer < items.len() {
        let (c_ch, c_orig, c_count, c_open, c_close) = match &items[closer] {
            Item::Delim {
                ch,
                orig,
                count,
                can_open,
                can_close,
            } => (*ch, *orig, *count, *can_open, *can_close),
            _ => {
                closer += 1;
                continue;
            }
        };
        if !c_close || c_count == 0 {
            closer += 1;
            continue;
        }
        // Look back for an opener.
        let mut opener = None;
        let mut k = closer;
        while k > 0 {
            k -= 1;
            if let Item::Delim {
                ch,
                orig,
                count,
                can_open,
                can_close,
            } = &items[k]
            {
                if *ch == c_ch && *can_open && *count > 0 {
                    let odd_match = (*can_close || c_open)
                        && (orig + c_orig) % 3 == 0
                        && !(orig % 3 == 0 && c_orig % 3 == 0);
                    if !odd_match {
                        opener = Some(k);
                        break;
                    }
                }
            }
        }
        match opener {
            Some(o) => {
                let o_count = match &items[o] {
                    Item::Delim { count, .. } => *count,
                    _ => unreachable!(),
                };
                let strong = o_count >= 2 && c_count >= 2;
                let take = if strong { 2 } else { 1 };
                // Children between o and closer.
                let children_items: Vec<Item> = items.drain(o + 1..closer).collect();
                let children = items_to_inlines(children_items);
                let node = if strong {
                    Inline::Strong(children)
                } else {
                    Inline::Emph(children)
                };
                // Now items[o] is opener, items[o+1] is closer.
                let mut remove_opener = false;
                let mut remove_closer = false;
                if let Item::Delim { count, .. } = &mut items[o] {
                    *count -= take;
                    if *count == 0 {
                        remove_opener = true;
                    }
                }
                if let Item::Delim { count, .. } = &mut items[o + 1] {
                    *count -= take;
                    if *count == 0 {
                        remove_closer = true;
                    }
                }
                items.insert(o + 1, Item::Node(node));
                // positions: o = opener, o+1 = node, o+2 = closer
                let mut closer_pos = o + 2;
                if remove_closer {
                    items.remove(closer_pos);
                }
                if remove_opener {
                    items.remove(o);
                    closer_pos -= 1;
                }
                closer = closer_pos;
            }
            None => {
                if !c_open {
                    // Can't be an opener either: becomes text (leave as delim with count; rendered literally).
                    if let Item::Delim { can_close, .. } = &mut items[closer] {
                        *can_close = false;
                    }
                }
                closer += 1;
            }
        }
    }
}
