//! Markdown rendering (CommonMark + tables + math), producing HTML in the
//! style of common Rust Markdown renderers.

pub mod block;
pub mod escape;
pub mod inline;

use block::{Align, Block, Document};
use inline::{Inline, InlineParser};
use std::collections::HashMap;

/// How an image destination should be rendered.
pub enum ImageTarget {
    /// A regular image with the given URL.
    Image(String),
    /// An audio element with the given URL.
    Audio(String),
}

pub type ImageResolver<'a> = &'a dyn Fn(&str) -> ImageTarget;

struct Writer<'a> {
    out: String,
    end_newline: bool,
    refs: &'a HashMap<String, block::LinkDef>,
    resolver: Option<ImageResolver<'a>>,
}

impl<'a> Writer<'a> {
    fn write(&mut self, s: &str) {
        if !s.is_empty() {
            self.out.push_str(s);
            self.end_newline = s.ends_with('\n');
        }
    }

    fn write_newline_if_needed(&mut self) {
        if !self.end_newline {
            self.write("\n");
        }
    }

    fn inlines(&self, text: &str) -> Vec<Inline> {
        InlineParser::new(text, self.refs).parse()
    }

    fn render_blocks(&mut self, blocks: &[Block], tight: bool) {
        for b in blocks {
            self.render_block(b, tight);
        }
    }

    fn render_block(&mut self, block: &Block, tight: bool) {
        match block {
            Block::Paragraph(text) => {
                let inl = self.inlines(text);
                if tight {
                    self.render_inlines(&inl);
                } else {
                    self.write_newline_if_needed();
                    self.write("<p>");
                    self.render_inlines(&inl);
                    self.write("</p>\n");
                }
            }
            Block::Heading { level, text } => {
                let inl = self.inlines(text);
                self.write_newline_if_needed();
                self.write(&format!("<h{}>", level));
                self.render_inlines(&inl);
                self.write(&format!("</h{}>\n", level));
            }
            Block::ThematicBreak => {
                self.write_newline_if_needed();
                self.write("<hr />\n");
            }
            Block::CodeBlock { info, text } => {
                self.write_newline_if_needed();
                match info {
                    Some(info) => {
                        let lang = info.split(' ').next().unwrap_or("");
                        let lang = inline::unescape(lang);
                        if lang.is_empty() {
                            self.write("<pre><code>");
                        } else {
                            let mut s = String::from("<pre><code class=\"language-");
                            escape::escape_attr(&lang, &mut s);
                            s.push_str("\">");
                            self.write(&s);
                        }
                    }
                    None => self.write("<pre><code>"),
                }
                let mut s = String::new();
                escape::escape_body(text, &mut s);
                self.write(&s);
                self.write("</code></pre>\n");
            }
            Block::HtmlBlock(html) => {
                self.write(html);
            }
            Block::BlockQuote(children) => {
                self.write_newline_if_needed();
                self.write("<blockquote>\n");
                self.render_blocks(children, false);
                self.write("</blockquote>\n");
            }
            Block::List {
                ordered,
                start,
                tight,
                items,
            } => {
                self.write_newline_if_needed();
                if *ordered {
                    if *start == 1 {
                        self.write("<ol>\n");
                    } else {
                        self.write(&format!("<ol start=\"{}\">\n", start));
                    }
                } else {
                    self.write("<ul>\n");
                }
                for item in items {
                    self.write_newline_if_needed();
                    self.write("<li>");
                    self.render_blocks(item, *tight);
                    self.write("</li>\n");
                }
                if *ordered {
                    self.write("</ol>\n");
                } else {
                    self.write("</ul>\n");
                }
            }
            Block::Table { aligns, head, rows } => {
                self.write_newline_if_needed();
                self.write("<table>");
                self.write("<thead><tr>");
                for (i, cell) in head.iter().enumerate() {
                    self.write_cell("th", aligns.get(i).copied().unwrap_or(Align::None), cell);
                }
                self.write("</tr></thead><tbody>\n");
                for row in rows {
                    self.write("<tr>");
                    for (i, cell) in row.iter().enumerate() {
                        self.write_cell("td", aligns.get(i).copied().unwrap_or(Align::None), cell);
                    }
                    self.write("</tr>\n");
                }
                self.write("</tbody></table>\n");
            }
        }
    }

    fn write_cell(&mut self, tag: &str, align: Align, text: &str) {
        match align {
            Align::None => self.write(&format!("<{}>", tag)),
            Align::Left => self.write(&format!("<{} style=\"text-align: left\">", tag)),
            Align::Center => self.write(&format!("<{} style=\"text-align: center\">", tag)),
            Align::Right => self.write(&format!("<{} style=\"text-align: right\">", tag)),
        }
        let inl = self.inlines(text);
        self.render_inlines(&inl);
        self.write(&format!("</{}>", tag));
    }

    fn render_inlines(&mut self, inlines: &[Inline]) {
        for inl in inlines {
            self.render_inline(inl);
        }
    }

    fn render_inline(&mut self, inl: &Inline) {
        match inl {
            Inline::Text(t) => {
                let mut s = String::new();
                escape::escape_body(t, &mut s);
                self.write(&s);
            }
            Inline::Code(t) => {
                let mut s = String::from("<code>");
                escape::escape_body(t, &mut s);
                s.push_str("</code>");
                self.write(&s);
            }
            Inline::Math { display, text } => {
                let mut s = String::from(if *display {
                    "<span class=\"math math-display\">"
                } else {
                    "<span class=\"math math-inline\">"
                });
                escape::escape_body(text, &mut s);
                s.push_str("</span>");
                self.write(&s);
            }
            Inline::Html(h) => self.write(h),
            Inline::SoftBreak => self.write("\n"),
            Inline::HardBreak => self.write("<br />\n"),
            Inline::Emph(children) => {
