                escape::escape_href(dest, &mut s);
                if let Some(t) = title {
                    s.push_str("\" title=\"");
                    escape::escape_attr(t, &mut s);
                }
                s.push_str("\">");
                self.write(&s);
                self.render_inlines(children);
                self.write("</a>");
            }
            Inline::Image {
