//! Scheduling: FSRS with default parameters.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Grade {
    Forgot,
    Hard,
    Good,
    Easy,
}

impl Grade {
    pub fn as_db_str(&self) -> &'static str {
        match self {
            Grade::Forgot => "forgot",
            Grade::Hard => "hard",
            Grade::Good => "good",
            Grade::Easy => "easy",
        }
    }

    fn number(&self) -> f64 {
        match self {
            Grade::Forgot => 1.0,
            Grade::Hard => 2.0,
            Grade::Good => 3.0,
            Grade::Easy => 4.0,
        }
    }
}

const W: [f64; 19] = [
    0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046, 1.54575, 0.1192, 1.01925,
    1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898, 0.51655, 0.6621,
];

const DECAY: f64 = -0.5;
const FACTOR: f64 = 19.0 / 81.0;
const DESIRED_RETENTION: f64 = 0.9;
const MAX_INTERVAL: i64 = 256;

#[derive(Debug, Clone, Copy)]
pub struct Schedule {
    pub stability: f64,
    pub difficulty: f64,
    pub interval_raw: f64,
    pub interval_days: i64,
}

fn initial_stability(g: Grade) -> f64 {
    match g {
        Grade::Forgot => W[0],
        Grade::Hard => W[1],
        Grade::Good => W[2],
        Grade::Easy => W[3],
    }
}

fn initial_difficulty(g: Grade) -> f64 {
    let d = W[4] - (W[5] * (g.number() - 1.0)).exp() + 1.0;
    d.clamp(1.0, 10.0)
}

fn retrievability(elapsed_days: f64, stability: f64) -> f64 {
    (1.0 + FACTOR * (elapsed_days / stability)).powf(DECAY)
}

fn next_difficulty(d: f64, g: Grade) -> f64 {
    let delta = -W[6] * (g.number() - 3.0);
    let damped = d + delta * ((10.0 - d) / 9.0);
    let d0_easy = W[4] - (W[5] * 3.0).exp() + 1.0;
    let reverted = W[7] * d0_easy + (1.0 - W[7]) * damped;
    reverted.clamp(1.0, 10.0)
}

fn stability_after_recall(d: f64, s: f64, r: f64, g: Grade) -> f64 {
    let hard = if g == Grade::Hard { W[15] } else { 1.0 };
    let easy = if g == Grade::Easy { W[16] } else { 1.0 };
    s * ((11.0 - d) * s.powf(-W[9]) * ((W[10] * (1.0 - r)).exp() - 1.0) * W[8].exp() * hard * easy
        + 1.0)
}

fn stability_after_forgetting(d: f64, s: f64, r: f64) -> f64 {
    let new_s = d.powf(-W[12]) * ((s + 1.0).powf(W[13]) - 1.0) * (W[14] * (1.0 - r)).exp() * W[11];
    new_s.min(s)
}

fn interval(stability: f64) -> (f64, i64) {
    let raw = stability / FACTOR * (DESIRED_RETENTION.powf(1.0 / DECAY) - 1.0);
    let days = raw.round() as i64;
    let days = days.clamp(1, MAX_INTERVAL);
    (raw, days)
}

/// Schedule a card that has never been reviewed.
pub fn schedule_new(g: Grade) -> Schedule {
    let stability = initial_stability(g);
    let difficulty = initial_difficulty(g);
    let (interval_raw, interval_days) = interval(stability);
    Schedule {
        stability,
        difficulty,
        interval_raw,
        interval_days,
    }
}

/// Schedule a card given its previous state and the days since the last review.
pub fn schedule_review(stability: f64, difficulty: f64, elapsed_days: i64, g: Grade) -> Schedule {
    let r = retrievability(elapsed_days as f64, stability);
    let new_s = match g {
        Grade::Forgot => stability_after_forgetting(difficulty, stability, r),
        _ => stability_after_recall(difficulty, stability, r, g),
    };
    let new_d = next_difficulty(difficulty, g);
    let (interval_raw, interval_days) = interval(new_s);
    Schedule {
        stability: new_s,
        difficulty: new_d,
        interval_raw,
        interval_days,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_cards() {
        let s = schedule_new(Grade::Good);
        assert_eq!(s.stability, 3.173);
        assert_eq!(s.difficulty, 5.282434422319005);
        assert_eq!(s.interval_raw, 3.172999999999999);
        assert_eq!(s.interval_days, 3);
        let s = schedule_new(Grade::Forgot);
        assert_eq!(s.interval_raw, 0.4025499999999999);
        assert_eq!(s.interval_days, 1);
    }

    #[test]
    fn reviews() {
        let s = schedule_review(3.173, 5.282434422319005, 10, Grade::Forgot);
        assert_eq!(s.stability, 1.4717624124106874);
        assert_eq!(s.difficulty, 6.796932579932992);
        let s = schedule_review(3.173, 5.282434422319005, 10, Grade::Hard);
        assert_eq!(s.stability, 7.970345678379021);
        assert_eq!(s.difficulty, 6.0349502556102195);
        let s = schedule_review(5.0, 1.05, 7, Grade::Easy);
        assert_eq!(s.stability, 88.19796727966929);
        assert_eq!(s.difficulty, 1.0);
        let s = schedule_review(0.001, 1.0, 365, Grade::Forgot);
        assert_eq!(s.stability, 0.001);
        let s = schedule_review(100.5, 9.7, 645, Grade::Good);
        assert_eq!(s.stability, 261.64191018969933);
        assert_eq!(s.interval_days, 256);
        let s = schedule_review(7.1949, 7.1949, 0, Grade::Good);
        assert_eq!(s.difficulty, 7.176636167311107);
    }
}
