//! HTML templates for the drill interface.

use crate::markdown::escape::escape_attr_string;

const HEAD: &str = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>hashcards</title><link rel=\"stylesheet\" href=\"/katex/katex.css\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\"><script defer src=\"/katex/katex.js\"></script><script defer src=\"/katex/mhchem.js\"></script><script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script><link rel=\"stylesheet\" href=\"/style.css\"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>";

const TAIL: &str = "<script src=\"/script.js\"></script></body></html>";

pub enum Controls {
    /// The card has not been revealed yet.
    Reveal,
    /// The card has been revealed: show the grade buttons.
    Grade { binary: bool },
}

pub struct CardPage<'a> {
    pub deck_name: &'a str,
    /// Already-rendered HTML for the card content area.
    pub content_html: &'a str,
    pub progress_pct: u64,
    pub can_undo: bool,
    pub controls: Controls,
}

pub fn card_page(p: &CardPage) -> String {
    let mut s = String::with_capacity(4096);
    s.push_str(HEAD);
    s.push_str("<div class=\"root\"><div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: ");
    s.push_str(&p.progress_pct.to_string());
    s.push_str("%;\"></div></div></div><div class=\"card-container\"><div class=\"card\"><div class=\"card-header\"><h1>");
    s.push_str(&escape_attr_string(p.deck_name));
    s.push_str("</h1></div><div class=\"card-content\">");
    s.push_str(p.content_html);
    s.push_str("</div></div></div><div class=\"controls\"><form action=\"/\" method=\"post\">");
    if p.can_undo {
        s.push_str("<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" title=\"Undo last action. Shortcut: u.\">");
    } else {
        s.push_str("<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" disabled>");
    }
    s.push_str("<div class=\"spacer\"></div>");
    match p.controls {
        Controls::Reveal => {
            s.push_str("<input id=\"reveal\" type=\"submit\" name=\"action\" value=\"Reveal\" title=\"Show the answer. Shortcut: space.\">");
        }
        Controls::Grade { binary: false } => {
            s.push_str("<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten. Shortcut: 1.\"><input id=\"hard\" type=\"submit\" name=\"action\" value=\"Hard\" title=\"Mark card as difficult. Shortcut: 2.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered well. Shortcut: 3.\"><input id=\"easy\" type=\"submit\" name=\"action\" value=\"Easy\" title=\"Mark card as very easy. Shortcut: 4.\"></div>");
        }
        Controls::Grade { binary: true } => {
            s.push_str("<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered.\"></div>");
        }
    }
    s.push_str("<div class=\"spacer\"></div><input id=\"end\" type=\"submit\" name=\"action\" value=\"End\" title=\"End the session (changes are saved)\"></form></div></div>");
    s.push_str(TAIL);
    s
}

pub struct FinishedPage<'a> {
    pub total_cards: usize,
    pub cards_reviewed: usize,
    pub started: &'a str,
    pub finished: &'a str,
    pub duration_secs: i64,
}

pub fn finished_page(p: &FinishedPage) -> String {
    let pace = if p.cards_reviewed == 0 {
        0.0
    } else {
        p.duration_secs as f64 / p.cards_reviewed as f64
    };
    let mut s = String::with_capacity(2048);
    s.push_str(HEAD);
    s.push_str("<div class=\"finished\"><h1>Session Completed 🎉</h1><div class=\"summary\">Reviewed ");
    s.push_str(&p.cards_reviewed.to_string());
    s.push_str(" cards in ");
    s.push_str(&p.duration_secs.to_string());
    s.push_str(" seconds.</div><h2>Session Stats</h2><div class=\"stats\"><table><tbody>");
    let row = |k: &str, v: &str| format!("<tr><td class=\"key\">{}</td><td class=\"val\">{}</td></tr>", k, v);
    s.push_str(&row("Total Cards", &p.total_cards.to_string()));
    s.push_str(&row("Cards Reviewed", &p.cards_reviewed.to_string()));
    s.push_str(&row("Started", p.started));
    s.push_str(&row("Finished", p.finished));
    s.push_str(&row("Duration (seconds)", &p.duration_secs.to_string()));
    s.push_str(&row("Pace (s/card)", &format!("{:.2}", pace)));
    s.push_str("</tbody></table></div><div class=\"shutdown-container\"><form action=\"/\" method=\"post\"><input class=\"shutdown-button\" id=\"shutdown\" type=\"submit\" name=\"action\" value=\"Shutdown\" title=\"Shut down the server\"></form></div></div>");
    s.push_str(TAIL);
    s
}

/// Render the content area for a basic card.
pub fn basic_content(question_html: &str, answer_html: Option<&str>) -> String {
    let mut s = String::new();
    s.push_str("<div class=\"question rich-text\">");
    s.push_str(question_html);
    s.push_str("</div><div class=\"answer rich-text\">");
    if let Some(a) = answer_html {
        s.push_str(a);
    }
    s.push_str("</div>");
    s
}

/// Render the content area for a cloze card.
pub fn cloze_content(prompt_html: &str) -> String {
    format!("<div class=\"prompt rich-text\">{}</div>", prompt_html)
}

/// The dynamic part of script.js: the TeX macros table.
pub fn script_js(macros: &[(String, String)]) -> String {
    let mut s = String::from("let MACROS = {};\n");
    for (name, def) in macros {
        s.push_str("MACROS['");
        s.push_str(&name.replace('\\', "\\\\"));
        s.push_str("'] = '");
        s.push_str(&def.replace('\\', "\\\\"));
        s.push_str("';\n");
    }
    s.push('\n');
    s.push_str(SCRIPT_JS_STATIC);
    s
}

pub const SCRIPT_JS_STATIC: &str = include_str!("../assets/script.js");
pub const STYLE_CSS: &[u8] = include_bytes!("../assets/style.css");
pub const KATEX_CSS: &[u8] = include_bytes!("../assets/katex/katex.css");
pub const KATEX_JS: &[u8] = include_bytes!("../assets/katex/katex.js");
