//! The drill web server: a small HTTP/1.1 server with a session state machine.

use crate::collection::{resolve_media, Collection};
use crate::db::{format_date, format_timestamp, Database, Performance, ReviewRow};
use crate::error::Error;
use crate::fsrs::{self, Grade};
use crate::html;
use crate::markdown::{self, ImageTarget};
use crate::parser::{Card, CardContent};
use chrono::{DateTime, NaiveDate, Utc};
use rand::seq::SliceRandom;
use std::collections::{HashSet, VecDeque};
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::{Component, Path, PathBuf};
use std::sync::{Arc, Mutex};

pub struct DrillOptions {
    pub card_limit: Option<usize>,
    pub new_card_limit: Option<usize>,
    pub host: String,
    pub port: u16,
    pub from_deck: Option<String>,
    pub open_browser: bool,
    pub binary_controls: bool,
    pub bury_siblings: bool,
}

const CLOZE_HIDDEN: &str = "\u{E000}\u{E001}\u{E002}";
const CLOZE_START: &str = "\u{E003}\u{E004}\u{E005}";
const CLOZE_END: &str = "\u{E006}\u{E007}\u{E008}";
const CLOZE_DOTS: &str = "<span class='cloze'>.............</span>";

#[derive(Clone)]
struct PendingReview {
    card_idx: usize,
    reviewed_at: String,
    grade: Grade,
    perf: Performance,
}

#[derive(Clone)]
struct Snapshot {
    queue: VecDeque<usize>,
    perf: Vec<Option<Performance>>,
    reviews: Vec<PendingReview>,
}

struct Session {
    cards: Vec<Card>,
    perf: Vec<Option<Performance>>,
    queue: VecDeque<usize>,
    revealed: bool,
    history: Vec<Snapshot>,
    reviews: Vec<PendingReview>,
    started_at: DateTime<Utc>,
    ended_at: Option<DateTime<Utc>>,
}

struct App {
    root: PathBuf,
    port: u16,
    binary_controls: bool,
    script_js: String,
    db: Database,
    session: Session,
}

fn today() -> NaiveDate {
    Utc::now().date_naive()
}

fn is_due(p: &Performance, today: &NaiveDate) -> bool {
    match p.due_date() {
        Some(d) => d <= *today,
        None => p.due_date.as_str() <= format_date(today).as_str(),
    }
}

/// Build the session queue from the collection.
fn build_queue(coll: &Collection, db: &Database, opts: &DrillOptions) -> Result<(Vec<Card>, Vec<Option<Performance>>), Error> {
    let today = today();
    let mut cards: Vec<&Card> = coll
        .cards
        .iter()
        .filter(|c| match &opts.from_deck {
            Some(d) => &c.deck_name == d,
            None => true,
        })
        .collect();
    cards.sort_by(|a, b| a.hash.cmp(&b.hash));

    let mut selected: Vec<(&Card, Option<Performance>)> = Vec::new();
    let mut new_count = 0usize;
    for card in cards {
        let perf = db.performance(&card.hash)?;
        match perf {
            None => {
                if opts.new_card_limit.map(|l| new_count < l).unwrap_or(true) {
                    new_count += 1;
                    selected.push((card, None));
                }
            }
            Some(p) => {
                if is_due(&p, &today) {
                    selected.push((card, Some(p)));
                }
            }
        }
    }
    if let Some(limit) = opts.card_limit {
        selected.truncate(limit);
    }
    if opts.bury_siblings {
        let mut seen: HashSet<String> = HashSet::new();
        selected.retain(|(c, _)| match &c.family_hash {
            Some(f) => seen.insert(f.clone()),
            None => true,
        });
    }
    let mut rng = rand::thread_rng();
    selected.shuffle(&mut rng);
    let perf = selected.iter().map(|(_, p)| p.clone()).collect();
    let cards = selected.into_iter().map(|(c, _)| c.clone()).collect();
    Ok((cards, perf))
}

pub fn drill(coll: Collection, db: Database, opts: DrillOptions) -> Result<(), Error> {
    // Register all cards in the database.
    let now = format_timestamp(&Utc::now());
    db.begin()?;
    for card in &coll.cards {
        db.insert_card_if_missing(&card.hash, &now)?;
    }
    db.commit()?;

    let (cards, perf) = build_queue(&coll, &db, &opts)?;
    if cards.is_empty() {
        println!("No cards due today.");
        return Ok(());
    }

    let listener = TcpListener::bind((opts.host.as_str(), opts.port)).map_err(Error::Io)?;

    let session = Session {
        queue: (0..cards.len()).collect(),
        cards,
        perf,
        revealed: false,
        history: Vec::new(),
        reviews: Vec::new(),
        started_at: Utc::now(),
        ended_at: None,
    };
    let app = Arc::new(Mutex::new(App {
        root: coll.root.clone(),
        port: opts.port,
        binary_controls: opts.binary_controls,
        script_js: html::script_js(&coll.macros),
        db,
        session,
    }));

    if opts.open_browser {
        let url = format!("http://{}:{}/", opts.host, opts.port);
        open_browser(&url);
    }

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let app = Arc::clone(&app);
                std::thread::spawn(move || {
                    handle_connection(stream, app);
                });
            }
            Err(_) => continue,
        }
    }
    Ok(())
}

fn open_browser(url: &str) {
    for cmd in ["xdg-open", "gio", "gnome-open", "kde-open", "wslview"] {
        let mut c = std::process::Command::new(cmd);
        if cmd == "gio" {
            c.arg("open");
        }
        c.arg(url);
        c.stdout(std::process::Stdio::null());
        c.stderr(std::process::Stdio::null());
        if let Ok(mut child) = c.spawn() {
            let _ = child.wait();
            return;
        }
    }
}

// ---------------------------------------------------------------------------
// HTTP plumbing
// ---------------------------------------------------------------------------

struct Request {
    method: String,
    path: String,
    http10: bool,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
    keep_alive: bool,
}

impl Request {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }
}

struct Response {
    status: u16,
    reason: &'static str,
    /// Handler-provided headers, in order.
    headers: Vec<(&'static str, String)>,
    body: Vec<u8>,
}

impl Response {
    fn new(status: u16, reason: &'static str) -> Self {
        Response {
            status,
            reason,
            headers: Vec::new(),
            body: Vec::new(),
        }
    }
    fn header(mut self, k: &'static str, v: impl Into<String>) -> Self {
        self.headers.push((k, v.into()));
        self
    }
    fn body(mut self, b: impl Into<Vec<u8>>) -> Self {
        self.body = b.into();
        self
    }
    fn html(status: u16, reason: &'static str, body: &str) -> Self {
        Response::new(status, reason)
            .header("content-type", "text/html; charset=utf-8")
            .body(body.as_bytes().to_vec())
    }
    fn text(status: u16, reason: &'static str, body: &str) -> Self {
        Response::new(status, reason)
            .header("content-type", "text/plain; charset=utf-8")
            .body(body.as_bytes().to_vec())
    }
    fn not_found() -> Self {
        Response::html(404, "Not Found", "Not Found")
    }
    fn redirect_home() -> Self {
        Response::new(303, "See Other").header("location", "/")
    }
    fn method_not_allowed(allow: &str) -> Self {
        Response::new(405, "Method Not Allowed").header("allow", allow)
    }
}

enum ReadOutcome {
    Request(Request),
    BadRequest,
    Closed,
}

fn http_date() -> String {
    Utc::now().format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

fn read_request(reader: &mut BufReader<TcpStream>) -> ReadOutcome {
    // Request line (skip leading empty lines).
    let mut line = String::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => return ReadOutcome::Closed,
            Ok(_) => {}
            Err(_) => return ReadOutcome::Closed,
        }
        let trimmed = line.trim_end_matches(['\r', '\n']);
        if trimmed.is_empty() {
            continue;
        }
        break;
    }
    let request_line = line.trim_end_matches(['\r', '\n']).to_string();
    let mut parts = request_line.split(' ');
    let method = parts.next().unwrap_or("").to_string();
    let target = parts.next().unwrap_or("").to_string();
    let version = parts.next().unwrap_or("").to_string();
    if parts.next().is_some() || method.is_empty() || target.is_empty() {
        return ReadOutcome::BadRequest;
    }
    if !method.bytes().all(|b| b.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&b)) {
        return ReadOutcome::BadRequest;
    }
    let http10 = match version.as_str() {
        "HTTP/1.1" => false,
        "HTTP/1.0" => true,
        _ => return ReadOutcome::BadRequest,
    };
    // Headers.
    let mut headers: Vec<(String, String)> = Vec::new();
    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => return ReadOutcome::Closed,
            Ok(_) => {}
            Err(_) => return ReadOutcome::Closed,
        }
        let l = line.trim_end_matches(['\r', '\n']);
        if l.is_empty() {
            break;
        }
        match l.find(':') {
            Some(idx) => {
                let name = l[..idx].trim().to_string();
                let value = l[idx + 1..].trim().to_string();
                if name.is_empty() || name.contains(' ') {
                    return ReadOutcome::BadRequest;
                }
                headers.push((name, value));
            }
            None => return ReadOutcome::BadRequest,
        }
    }
    // Path: strip scheme/authority for absolute-form targets.
    let mut path = target.clone();
    if let Some(rest) = path.strip_prefix("http://").or_else(|| path.strip_prefix("https://")) {
        match rest.find('/') {
            Some(i) => path = rest[i..].to_string(),
            None => path = "/".to_string(),
        }
    }
    if !path.starts_with('/') && path != "*" {
        return ReadOutcome::BadRequest;
    }
    if path.bytes().any(|b| b <= b' ' || b == 0x7f) {
        return ReadOutcome::BadRequest;
    }
    let conn = headers
        .iter()
        .find(|(k, _)| k.eq_ignore_ascii_case("connection"))
        .map(|(_, v)| v.to_ascii_lowercase());
    let keep_alive = match (&conn, http10) {
        (Some(c), _) if c.split(',').any(|t| t.trim() == "close") => false,
        (Some(c), true) => c.split(',').any(|t| t.trim() == "keep-alive"),
        (None, true) => false,
        _ => true,
    };
    // Expect: 100-continue.
    let expects_continue = headers
        .iter()
        .any(|(k, v)| k.eq_ignore_ascii_case("expect") && v.eq_ignore_ascii_case("100-continue"));
    // Body.
    let mut body = Vec::new();
    let chunked = headers.iter().any(|(k, v)| {
        k.eq_ignore_ascii_case("transfer-encoding") && v.to_ascii_lowercase().contains("chunked")
    });
    let content_length = headers
        .iter()
        .find(|(k, _)| k.eq_ignore_ascii_case("content-length"))
        .map(|(_, v)| v.trim().parse::<usize>());
    if expects_continue {
        let _ = reader.get_mut().write_all(b"HTTP/1.1 100 Continue\r\n\r\n");
        let _ = reader.get_mut().flush();
    }
    if chunked {
        loop {
            line.clear();
            if reader.read_line(&mut line).unwrap_or(0) == 0 {
                return ReadOutcome::Closed;
            }
            let size_str = line.trim().split(';').next().unwrap_or("").trim();
            let size = match usize::from_str_radix(size_str, 16) {
                Ok(n) => n,
                Err(_) => return ReadOutcome::BadRequest,
            };
            if size == 0 {
                // Trailers until empty line.
                loop {
                    line.clear();
                    if reader.read_line(&mut line).unwrap_or(0) == 0 {
                        break;
                    }
                    if line.trim_end_matches(['\r', '\n']).is_empty() {
                        break;
                    }
                }
                break;
            }
            let mut chunk = vec![0u8; size];
            if reader.read_exact(&mut chunk).is_err() {
                return ReadOutcome::Closed;
            }
            body.extend_from_slice(&chunk);
            line.clear();
            let _ = reader.read_line(&mut line);
        }
    } else if let Some(cl) = content_length {
        match cl {
            Ok(n) => {
                body = vec![0u8; n];
                if n > 0 && reader.read_exact(&mut body).is_err() {
                    return ReadOutcome::Closed;
                }
            }
            Err(_) => return ReadOutcome::BadRequest,
        }
    }
    ReadOutcome::Request(Request {
        method,
        path,
        http10,
        headers,
        body,
        keep_alive,
    })
}

fn write_response(stream: &mut TcpStream, resp: &Response, http10: bool, keep_alive: bool, head: bool) -> std::io::Result<()> {
    let mut out = String::new();
    let version = if http10 { "HTTP/1.0" } else { "HTTP/1.1" };
    out.push_str(&format!("{} {} {}\r\n", version, resp.status, resp.reason));
    for (k, v) in &resp.headers {
        out.push_str(&format!("{}: {}\r\n", k, v));
    }
    let conn_header = if http10 && keep_alive {
        Some("keep-alive")
    } else if !http10 && !keep_alive {
        Some("close")
    } else {
        None
    };
    if resp.body.is_empty() {
        if let Some(c) = conn_header {
            out.push_str(&format!("connection: {}\r\n", c));
        }
        out.push_str("content-length: 0\r\n");
    } else {
        out.push_str(&format!("content-length: {}\r\n", resp.body.len()));
        if let Some(c) = conn_header {
            out.push_str(&format!("connection: {}\r\n", c));
        }
    }
    out.push_str(&format!("date: {}\r\n\r\n", http_date()));
    stream.write_all(out.as_bytes())?;
    if !head {
        stream.write_all(&resp.body)?;
    }
    stream.flush()
}

fn handle_connection(stream: TcpStream, app: Arc<Mutex<App>>) {
    let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(600)));
    let mut reader = BufReader::new(match stream.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    });
    let mut writer = stream;
    loop {
        match read_request(&mut reader) {
            ReadOutcome::Closed => return,
            ReadOutcome::BadRequest => {
                let resp = Response::new(400, "Bad Request");
                let _ = write_response(&mut writer, &resp, false, false, false);
                let _ = writer.shutdown(std::net::Shutdown::Both);
                return;
            }
            ReadOutcome::Request(req) => {
                let head = req.method == "HEAD";
                let (resp, shutdown) = handle_request(&req, &app);
                let keep_alive = req.keep_alive;
                let _ = write_response(&mut writer, &resp, req.http10, keep_alive, head);
                if shutdown {
                    let _ = writer.flush();
                    let _ = writer.shutdown(std::net::Shutdown::Both);
                    std::process::exit(0);
                }
                if !keep_alive {
                    let _ = writer.shutdown(std::net::Shutdown::Both);
                    return;
                }
            }
        }
    }
}

fn percent_decode_bytes(s: &str) -> Vec<u8> {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 1 && i + 2 <= bytes.len() - 1 {
            if let (Some(h), Some(l)) = (
                (bytes[i + 1] as char).to_digit(16),
                (bytes[i + 2] as char).to_digit(16),
            ) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    out
}

fn percent_decode_lossy(s: &str) -> String {
    String::from_utf8_lossy(&percent_decode_bytes(s)).into_owned()
}

/// Parse an `application/x-www-form-urlencoded` body into a list of pairs.
fn parse_form(body: &[u8]) -> Vec<(String, String)> {
    let s = String::from_utf8_lossy(body);
    let mut out = Vec::new();
    for pair in s.split('&') {
        if pair.is_empty() {
            continue;
        }
        let (k, v) = match pair.find('=') {
            Some(i) => (&pair[..i], &pair[i + 1..]),
            None => (pair, ""),
        };
        let dec = |x: &str| percent_decode_lossy(&x.replace('+', " "));
        out.push((dec(k), dec(v)));
    }
    out
}

fn is_form_content_type(ct: Option<&str>) -> bool {
    match ct {
        Some(ct) => {
            let mime = ct.split(';').next().unwrap_or("").trim();
            mime == "application/x-www-form-urlencoded"
        }
        None => false,
    }
}

const ACTIONS: &[&str] = &["Reveal", "Undo", "End", "Forgot", "Hard", "Good", "Easy", "Shutdown"];

fn content_type_for(path: &Path) -> &'static str {
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
        .unwrap_or_default();
    match ext.as_str() {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "ogg" => "audio/ogg",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        _ => "application/octet-stream",
    }
}

fn handle_request(req: &Request, app: &Arc<Mutex<App>>) -> (Response, bool) {
    let path_only = req.path.split('?').next().unwrap_or("").split('#').next().unwrap_or("");
    let is_get = req.method == "GET" || req.method == "HEAD";

    // Static assets.
    let static_asset: Option<(&[u8], &str, bool)> = match path_only {
        "/style.css" => Some((html::STYLE_CSS, "text/css", true)),
        "/katex/katex.css" => Some((html::KATEX_CSS, "text/css", true)),
        "/katex/katex.js" => Some((html::KATEX_JS, "text/javascript", true)),
        "/katex/mhchem.js" => Some((html::MHCHEM_JS, "text/javascript", true)),
        _ => None,
    };
    if let Some((bytes, ct, cache)) = static_asset {
        if !is_get {
            return (Response::method_not_allowed("GET,HEAD"), false);
        }
        let mut r = Response::new(200, "OK").header("content-type", ct);
        if cache {
            r = r.header("cache-control", "public, max-age=604800, immutable");
        }
        return (r.body(bytes.to_vec()), false);
    }
    if path_only == "/script.js" {
        if !is_get {
            return (Response::method_not_allowed("GET,HEAD"), false);
        }
        let js = app.lock().unwrap().script_js.clone();
        return (
            Response::new(200, "OK")
                .header("content-type", "text/javascript")
                .body(js.into_bytes()),
            false,
        );
    }
    if let Some(rest) = path_only.strip_prefix("/katex/fonts/") {
        if rest.is_empty() {
            return (Response::not_found(), false);
        }
        if !is_get {
            return (Response::method_not_allowed("GET,HEAD"), false);
        }
        let name = percent_decode_lossy(rest);
        match html::FONTS.iter().find(|(n, _)| *n == name) {
            Some((_, bytes)) => {
                return (
                    Response::new(200, "OK")
                        .header("content-type", "font/woff2")
                        .header("cache-control", "public, max-age=604800, immutable")
                        .body(bytes.to_vec()),
                    false,
                )
            }
            None => {
                return (
                    Response::new(404, "Not Found")
                        .header("content-type", "text/plain")
                        .header("cache-control", "no-cache")
                        .body(b"Not Found".to_vec()),
                    false,
                )
            }
        }
    }
    if let Some(rest) = path_only.strip_prefix("/file/") {
        if rest.is_empty() {
            return (Response::not_found(), false);
        }
        if !is_get {
            return (Response::method_not_allowed("GET,HEAD"), false);
        }
        let rel = percent_decode_lossy(rest);
        let root = app.lock().unwrap().root.clone();
        let rel_path = Path::new(&rel);
        let traversal = rel_path.components().any(|c| matches!(c, Component::ParentDir));
        let not_found = || {
            Response::new(404, "Not Found")
                .header("content-type", "text/plain")
                .body(b"Not Found".to_vec())
        };
        if traversal {
            return (not_found(), false);
        }
        let full = root.join(rel_path);
        match std::fs::read(&full) {
            Ok(bytes) => {
                return (
                    Response::new(200, "OK")
                        .header("content-type", content_type_for(&full))
                        .body(bytes),
                    false,
                )
            }
            Err(_) => return (not_found(), false),
        }
    }
    if path_only == "/" {
        match req.method.as_str() {
            "GET" | "HEAD" => {
                let app = app.lock().unwrap();
                return (Response::html(200, "OK", &render_page(&app)), false);
            }
            "POST" => {
                if !is_form_content_type(req.header("content-type")) {
                    return (
                        Response::text(
                            415,
                            "Unsupported Media Type",
                            "Form requests must have `Content-Type: application/x-www-form-urlencoded`",
                        ),
                        false,
                    );
                }
                let pairs = parse_form(&req.body);
                let mut action: Option<String> = None;
                for (k, v) in pairs {
                    if k == "action" {
                        if action.is_some() {
                            return (
                                Response::text(
                                    422,
                                    "Unprocessable Entity",
                                    "Failed to deserialize form body: duplicate field `action`",
                                ),
                                false,
                            );
                        }
                        action = Some(v);
                    }
                }
                let action = match action {
                    Some(a) => a,
                    None => {
                        return (
                            Response::text(
                                422,
                                "Unprocessable Entity",
                                "Failed to deserialize form body: missing field `action`",
                            ),
                            false,
                        )
                    }
                };
                if !ACTIONS.contains(&action.as_str()) {
                    let expected = ACTIONS
                        .iter()
                        .map(|a| format!("`{}`", a))
                        .collect::<Vec<_>>()
                        .join(", ");
                    return (
                        Response::text(
                            422,
                            "Unprocessable Entity",
                            &format!(
                                "Failed to deserialize form body: action: unknown variant `{}`, expected one of {}",
                                action, expected
                            ),
                        ),
                        false,
                    );
                }
                let mut app = app.lock().unwrap();
                let shutdown = perform_action(&mut app, &action);
                return (Response::redirect_home(), shutdown);
            }
            _ => return (Response::method_not_allowed("GET,HEAD,POST"), false),
        }
    }
    (Response::not_found(), false)
}

// ---------------------------------------------------------------------------
// Session logic
// ---------------------------------------------------------------------------

fn perform_action(app: &mut App, action: &str) -> bool {
    let now = Utc::now();
    let finished = app.session.ended_at.is_some();
    match action {
        "Reveal" => {
            if !finished && !app.session.queue.is_empty() {
                app.session.revealed = true;
            }
        }
        "Undo" => {
            if !finished {
                if let Some(snap) = app.session.history.pop() {
                    app.session.queue = snap.queue;
                    app.session.perf = snap.perf;
                    app.session.reviews = snap.reviews;
                    app.session.revealed = false;
                }
            }
        }
        "Forgot" | "Hard" | "Good" | "Easy" => {
            let grade = match action {
                "Forgot" => Grade::Forgot,
                "Hard" => Grade::Hard,
                "Good" => Grade::Good,
                _ => Grade::Easy,
            };
            if !finished && app.session.revealed {
                if let Some(&idx) = app.session.queue.front() {
                    let snapshot = Snapshot {
                        queue: app.session.queue.clone(),
                        perf: app.session.perf.clone(),
                        reviews: app.session.reviews.clone(),
                    };
                    app.session.history.push(snapshot);
                    let today = now.date_naive();
                    let sched = match &app.session.perf[idx] {
                        None => fsrs::schedule_new(grade),
                        Some(p) => {
                            let last = p.last_reviewed_date().unwrap_or(today);
                            let elapsed = (today - last).num_days();
                            fsrs::schedule_review(p.stability, p.difficulty, elapsed, grade)
                        }
                    };
                    let prev_count = app.session.perf[idx].as_ref().map(|p| p.review_count).unwrap_or(0);
                    let due = today + chrono::Duration::days(sched.interval_days);
                    let new_perf = Performance {
                        last_reviewed_at: format_timestamp(&now),
                        stability: sched.stability,
                        difficulty: sched.difficulty,
                        interval_raw: sched.interval_raw,
                        interval_days: sched.interval_days,
                        due_date: format_date(&due),
                        review_count: prev_count + 1,
                    };
                    app.session.reviews.push(PendingReview {
                        card_idx: idx,
                        reviewed_at: format_timestamp(&now),
                        grade,
                        perf: new_perf.clone(),
                    });
                    app.session.perf[idx] = Some(new_perf);
                    app.session.queue.pop_front();
                    if matches!(grade, Grade::Forgot | Grade::Hard) {
                        app.session.queue.push_back(idx);
                    }
                    app.session.revealed = false;
                    if app.session.queue.is_empty() {
                        finish_session(app, now);
                    }
                }
            }
        }
        "End" => {
            finish_session(app, now);
        }
        "Shutdown" => {
            if finished {
                return true;
            }
        }
        _ => {}
    }
    false
}

fn finish_session(app: &mut App, now: DateTime<Utc>) {
    app.session.ended_at = Some(now);
    let started = format_timestamp(&app.session.started_at);
    let ended = format_timestamp(&now);
    let db = &app.db;
    let _ = db.begin();
    if let Ok(session_id) = db.insert_session(&started, &ended) {
        for r in &app.session.reviews {
            let card = &app.session.cards[r.card_idx];
            let row = ReviewRow {
                review_id: 0,
                card_hash: card.hash.clone(),
                reviewed_at: r.reviewed_at.clone(),
                grade: r.grade.as_db_str().to_string(),
                stability: r.perf.stability,
                difficulty: r.perf.difficulty,
                interval_raw: r.perf.interval_raw,
                interval_days: r.perf.interval_days,
                due_date: r.perf.due_date.clone(),
            };
            let _ = db.insert_review(session_id, &row);
            let _ = db.update_card_performance(&card.hash, &r.perf);
        }
    }
    let _ = db.commit();
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

fn render_page(app: &App) -> String {
    let s = &app.session;
    if let Some(ended) = s.ended_at {
        let total = s.cards.len();
        let reviewed = total - s.queue.len();
        let duration = (ended - s.started_at).num_seconds();
        return html::finished_page(&html::FinishedPage {
            total_cards: total,
            cards_reviewed: reviewed,
            started: &s.started_at.format("%Y-%m-%d %H:%M:%S").to_string(),
            finished: &ended.format("%Y-%m-%d %H:%M:%S").to_string(),
            duration_secs: duration,
        });
    }
    let idx = match s.queue.front() {
        Some(&i) => i,
        None => {
            // Should not happen (session finishes when the queue empties).
            return html::finished_page(&html::FinishedPage {
                total_cards: s.cards.len(),
                cards_reviewed: s.cards.len(),
                started: &s.started_at.format("%Y-%m-%d %H:%M:%S").to_string(),
                finished: &s.started_at.format("%Y-%m-%d %H:%M:%S").to_string(),
                duration_secs: 0,
            });
        }
    };
    let card = &s.cards[idx];
    let total = s.cards.len();
    let done = total - s.queue.len();
    let progress = (done * 100 / total) as u64;
    let deck_dir = card.file_path.parent().unwrap_or(&app.root).to_path_buf();
    let root = app.root.clone();
    let port = app.port;
    let resolver = move |dest: &str| -> ImageTarget {
        let url_path = match resolve_media(&root, &deck_dir, dest) {
            Some(p) => {
                let canon = std::fs::canonicalize(&p).unwrap_or(p);
                match canon.strip_prefix(&root) {
                    Ok(rel) => rel
                        .components()
                        .map(|c| c.as_os_str().to_string_lossy().into_owned())
                        .collect::<Vec<_>>()
                        .join("/"),
                    Err(_) => canon.to_string_lossy().into_owned(),
                }
            }
            None => dest.to_string(),
        };
        let url = format!("http://localhost:{}/file/{}", port, url_path);
        if dest.ends_with(".mp3") || dest.ends_with(".wav") || dest.ends_with(".ogg") {
            ImageTarget::Audio(url)
        } else {
            ImageTarget::Image(url)
        }
    };
    let content_html = match &card.content {
        CardContent::Basic { question, answer } => {
            let q = markdown::render_html(question, Some(&resolver));
            let a = if s.revealed {
                Some(markdown::render_html(answer, Some(&resolver)))
            } else {
                None
            };
            html::basic_content(&q, a.as_deref())
        }
        CardContent::Cloze { text, start, end } => {
            let start = *start as usize;
            let end_excl = (*end as usize).wrapping_add(1);
            let (prefix, hidden, suffix) = split_cloze(text, start, end_excl);
            let rendered = if s.revealed {
                let src = format!("{}{}{}{}{}", prefix, CLOZE_START, hidden, CLOZE_END, suffix);
                markdown::render_html(&src, Some(&resolver))
                    .replace(CLOZE_START, "<span class='cloze-reveal'>")
                    .replace(CLOZE_END, "</span>")
            } else {
                let src = format!("{}{}{}", prefix, CLOZE_HIDDEN, suffix);
                markdown::render_html(&src, Some(&resolver)).replace(CLOZE_HIDDEN, CLOZE_DOTS)
            };
            html::cloze_content(&rendered)
        }
    };
    html::card_page(&html::CardPage {
        deck_name: &card.deck_name,
        content_html: &content_html,
        progress_pct: progress,
        can_undo: !s.history.is_empty(),
        controls: if s.revealed {
            html::Controls::Grade {
                binary: app.binary_controls,
            }
        } else {
            html::Controls::Reveal
        },
    })
}

/// Split a cloze text into (prefix, cloze, suffix) using byte offsets,
/// tolerating offsets that do not fall on character boundaries.
fn split_cloze(text: &str, start: usize, end_excl: usize) -> (String, String, String) {
    let n = text.len();
    let mut s = start.min(n);
    let mut e = end_excl.min(n).max(s);
    while s > 0 && !text.is_char_boundary(s) {
        s -= 1;
    }
    while e < n && !text.is_char_boundary(e) {
        e += 1;
    }
    (text[..s].to_string(), text[s..e].to_string(), text[e..].to_string())
}
