    let mut state: u64 = 0x1234_5678_9abc_def0;
    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let n: usize = std::env::args().nth(1).and_then(|a| a.parse().ok()).unwrap_or(20000);
    for i in 0..n {
        let k = (next() % 20) as usize + 1;
        let mut s = String::new();
        for _ in 0..k {
            s.push_str(tokens[(next() % tokens.len() as u64) as usize]);
        }
        let resolver = |dest: &str| hashcards::markdown::ImageTarget::Image(dest.to_string());
        let out = hashcards::markdown::render_html(&s, Some(&resolver));
        let _ = hashcards::markdown::image_urls(&s);
        // Also exercise the deck parser with the text as a card.
        let deck = format!("Q: {}\nA: {}\n\nC: [{}] {}\n", s, s, s, s);
        let _ = hashcards::parser::parse_deck(std::path::Path::new("/x/D.md"), "D", &deck);
        if i % 5000 == 0 {
            eprintln!("{} ok ({} bytes)", i, out.len());
        }
    }
    println!("done");
}
